DG.put("brahmaa-avtaar/16",{"n":16,"title":"ਅਥ ਅਜ ਰਾਜਾ ਕੋ ਰਾਜ ਕਥਨੰ","title_roman":"Ath aj raajaa ko raaj kathnan","page":803,"blocks":[{"type":"heading","kind":"chhand","name":"ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਪਾਧੜੀ ਛੰਦ","roman":"Paadhree chhand","meaning_en":"Padhri metre.","page":803,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":803,"lines":[{"gurmukhi":"ਫੁਨਿ ਭਏ ਰਾਜ ਅਜਰਾਜ ਬੀਰ। ਜਿਨਿ ਭਾਤਿ ਭਾਤਿ ਜਿਤੇ ਪ੍ਰਬੀਰ।","roman":"Phuni bhae raaj ajraaj beer | jini bhaati bhaati jite prabeer |","meaning_en":"Then the hero Aj became king, who conquered great warriors in many ways,","page":803,"meaning_status":"draft"},{"gurmukhi":"ਕਿਨੇ ਖਰਾਬ ਖਾਨੇ ਖਵਾਸ। ਜਿਤੇ ਮਹੀਪ ਤੋਰੇ ਮਵਾਸ। ੧।","roman":"Kine kharaab khaane khavaas | jite maheep tore mavaas | 1 |","meaning_en":"ruined the private chambers (of foes), conquered kings and broke the rebels.","page":803,"meaning_status":"draft","note":"ਖਾਨੇ ਖਵਾਸ: Persian, 'private quarters/attendants'; uncertain."}]},{"type":"verse","number":[2],"number_text":"੨।","page":803,"lines":[{"gurmukhi":"ਜਿਤੇ ਅਜੀਤ ਮੁੰਡੇ ਅਮੁੰਡ। ਖੰਡੇ ਅਖੰਡ ਕਿਨੇ ਘਮੰਡ।","roman":"Jite ajeet munde amund | khande akhand kine ghamand |","meaning_en":"He conquered the unconquered, shaved the unshaven, broke the unbreakable and crushed pride;","page":803,"meaning_status":"draft","note":"ਮੁੰਡੇ ਅਮੁੰਡ: read as 'humbled the unhumbled'; uncertain."},{"gurmukhi":"ਦਸ ਚਾਰਿ ਚਾਰਿ ਬਿਦਿਆ ਨਿਧਾਨ। ਅਜਰਾਜ ਰਾਜ ਰਾਜਾ ਮਹਾਨ। ੨।","roman":"Das chaari chaari bidiaa nidhaan | ajraaj raaj raajaa mahaan | 2 |","meaning_en":"a treasury of the eighteen sciences was King Aj, great king among kings.","page":803,"meaning_status":"draft"}]},{"type":"verse","number":[3],"number_text":"੩।","page":803,"lines":[{"gurmukhi":"ਸੂਰਾ ਸੁਬਾਹ ਜੋਧਾ ਪ੍ਰਚੰਡ। ਸ੍ਰੁਤਿ ਸਰਬ ਸਾਸਤ੍ਰ ਬਿਦਿਆ ਉਦੰਡ।","roman":"Sooraa subaah jodhaa prachand | sruti sarab saasatr bidiaa udand |","meaning_en":"Brave, long-armed, a fierce warrior, mighty in the Vedas, all the Shastras and learning,","page":803,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨੀ ਮਹਾਨ ਸੁੰਦਰ ਸਰੂਪ। ਅਵਿਲੋਕਿ ਜਾਸੁ ਲਾਜੰਤ ਭੂਪ। ੩।","roman":"Maanee mahaan sundar saroop | aviloki jaasu laajant bhoop | 3 |","meaning_en":"greatly honoured and beautiful of form; seeing him, kings felt ashamed.","page":803,"meaning_status":"draft"}]},{"type":"verse","number":[4],"number_text":"੪।","page":803,"lines":[{"gurmukhi":"ਰਾਜਾਨ ਰਾਜ ਰਾਜਾਧਿਰਾਜ। ਗ੍ਰਿਹ ਭਰੇ ਸਰਬ ਸੰਪਤਿ ਸਮਾਜ।","roman":"Raajaan raaj raajaadhiraaj | grih bhare sarab sanpti samaaj |","meaning_en":"King of kings, supreme sovereign, his house filled with all wealth and goods;","page":803,"meaning_status":"draft"},{"gurmukhi":"ਅਵਿਲੋਕ ਰੂਪ ਰੀਝੰਤ ਨਾਰਿ। ਸ੍ਰੁਤਿ ਦਾਨ ਸੀਲ ਬਿਦਿਆ ਉਦਾਰ। ੪।","roman":"Avilok roop reejhant naari | sruti daan seel bidiaa udaar | 4 |","meaning_en":"seeing his beauty, women were charmed; he was generous in Vedic learning, charity, good conduct and knowledge.","page":803,"meaning_status":"draft"}]},{"type":"verse","number":[5],"number_text":"੫।","page":803,"lines":[{"gurmukhi":"ਜੌ ਕਹੋ ਕਥਾ ਬਾਢੰਤ ਗ੍ਰੰਥ। ਸੁਣਿ ਲੇਹੁ ਮਿਤ੍ਰ ਸੰਛੇਪ ਕੰਥ।","roman":"Jau kaho kathaa baadhant granth | suni lehu mitr sanchhep kanth |","meaning_en":"If I tell the whole story the book will grow long; hear it in brief, my friend.","page":803,"meaning_status":"draft","note":"ਕੰਥ: read as 'story' (kathaa) or 'friend'; uncertain."},{"gurmukhi":"ਬੈਦਰਭ ਦੇਸਿ ਰਾਜਾ ਸੁਬਾਹ। ਚੰਪਾਵਤੀ ਸੁ ਗ੍ਰਿਹ ਨਾਰਿ ਤਾਹਿ। ੫।","roman":"Baidrabh desi raajaa subaah | chanpaavtee su grih naari taahi | 5 |","meaning_en":"In the land of Vidarbha was King Subahu; Champavati was his wife at home.","page":803,"meaning_status":"draft"}]},{"type":"verse","number":[6],"number_text":"੬।","page":803,"lines":[{"gurmukhi":"ਤਿਹ ਜਈ ਏਕ ਕਨਿਆ ਅਪਾਰ। ਤਿਹ ਮਤੀਇੰਦ੍ਰ ਨਾਮਾ ਉਦਾਰ।","roman":"Tih jaee ek kaniaa apaar | tih mateeindr naamaa udaar |","meaning_en":"She bore one daughter, beyond compare, by the noble name of Matiindra.","page":803,"meaning_status":"draft","note":"Name printed ਮਤੀਇੰਦ੍ਰ; transliterated as Matiindra (traditionally Indumati); uncertain."},{"gurmukhi":"ਜਬ ਭਈ ਜੋਗ ਬਰ ਕੇ ਕੁਮਾਰਿ। ਤਬ ਕੀਨ ਬੈਠਿ ਰਾਜਾ ਬਿਚਾਰਿ। ੬।","roman":"Jab bhaee jog bar ke kumaari | tab keen baithi raajaa bichaari | 6 |","meaning_en":"When the princess became ready for marriage, the king sat and thought it over.","page":803,"meaning_status":"draft"}]},{"type":"verse","number":[7],"number_text":"੭।","page":803,"lines":[{"gurmukhi":"ਲਿਨੇ ਬੁਲਾਇ ਨ੍ਰਿਪ ਸਰਬ ਦੇਸ। ਧਾਏ ਸੁਬਾਹ ਲੈ ਦਲ ਅਸੇਸ।","roman":"Line bulaai nrip sarab des | dhaae subaah lai dal ases |","meaning_en":"He summoned the kings of all lands; they rushed to Subahu with all their forces.","page":803,"meaning_status":"draft"},{"gurmukhi":"ਮੁਖ ਭਈ ਆਨਿ ਸਰਸ੍ਵਤੀ ਆਪੁ। ਜਿਹਿ ਜਪਤ ਲੋਗ ਮਿਲਿ ਸਰਬ ਜਾਪੁ। ੭।","roman":"Mukh bhaee aani sarsvatee aapu | jihi japat log mili sarab jaapu | 7 |","meaning_en":"Sarasvati herself came and was spokeswoman (for the princess), she whose name all people together repeat.","page":803,"meaning_status":"draft","note":"ਮੁਖ ਭਈ: read as 'became the speaker/leader'; uncertain."}]},{"type":"verse","number":[8],"number_text":"੮।","page":803,"lines":[{"gurmukhi":"ਤਬ ਦੇਸ ਦੇਸ ਕੇ ਭੂਪ ਆਨਿ। ਕਿਨੋ ਪ੍ਰਣਾਮ ਰਾਜਾ ਮਹਾਨਿ।","roman":"Tab des des ke bhoop aani | kino pranaam raajaa mahaani |","meaning_en":"Then the kings of many lands came and bowed to the great king.","page":803,"meaning_status":"draft"},{"gurmukhi":"ਤਹ ਬੈਠਿ ਰਾਜ ਸੋਭੰਤ ਐਸੁ। ਜਨ ਦੇਵ ਮੰਡਲੀ ਸਮ ਨ ਤੈਸੁ। ੮।","roman":"Tah baithi raaj sobhant aisu | jan dev mandlee sam na taisu | 8 |","meaning_en":"The kings sitting there shone so that even the company of gods was not equal to them.","page":803,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":804,"lines":[{"gurmukhi":"ਬਾਜੰਤ ਢੋਲ ਦੁੰਦਭਿ ਅਪਾਰ। ਬਾਜੰਤ ਤੂਰ ਝਨਕੰਤ ਤਾਰ।","roman":"Baajant dhol dundbhi apaar | baajant toor jhankant taar |","meaning_en":"Countless drums and kettledrums sounded; trumpets played and strings jingled.","page":804,"meaning_status":"draft"},{"gurmukhi":"ਸੋਭਾ ਅਪਾਰ ਬਰਨੀ ਨ ਜਾਇ। ਜਨੁ ਬੈਠਿ ਇੰਦ੍ਰ ਆਭਾ ਬਨਾਇ। ੯।","roman":"Sobhaa apaar barnee na jaai | janu baithi indr aabhaa banaai | 9 |","meaning_en":"The boundless splendour cannot be described; it was as if Indra sat there in his radiance.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":804,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਰਾਜ ਮੰਡਲੀ ਬੈਠਿ। ਅਵਿਲੋਕਿ ਇੰਦ੍ਰ ਜਹ ਨਾਕ ਐਠਿ।","roman":"Ih bhaati raaj mandlee baithi | aviloki indr jah naak aithi |","meaning_en":"In this way the assembly of kings sat; seeing it, even Indra turned up his nose (in envy).","page":804,"meaning_status":"draft","note":"ਨਾਕ ਐਠਿ: 'twisted the nose'; may be 'Indra was humbled'; uncertain."},{"gurmukhi":"ਆਭਾ ਅਪਾਰ ਬਰਨੇ ਸੁ ਕਉਨ। ਹ੍ਵੈ ਰਹੇ ਜਛ ਗੰਧ੍ਰਬ ਮਉਨ। ੧੦।","roman":"Aabhaa apaar barne su kaun | hvai rahe jachh gandhrab maun | 10 |","meaning_en":"Who could describe its boundless splendour? Yakshas and Gandharvas fell silent.","page":804,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅਰਧ ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਅਰਧ ਪਾਧੜੀ ਛੰਦ","roman":"Aradh paadhree chhand","meaning_en":"Ardh Padhri metre.","page":804,"meaning_status":"draft"},{"type":"verse","number":[11],"number_text":"੧੧।","page":804,"lines":[{"gurmukhi":"ਸੋਭੰਤ ਸੂਰ। ਲੋਭੰਤ ਹੂਰ।","roman":"Sobhant soor | lobhant hoor |","meaning_en":"The heroes shone; the houris were drawn by them;","page":804,"meaning_status":"draft","note":"ਹੂਰ: Persian/Arabic 'houri', heavenly maiden."},{"gurmukhi":"ਅਛ੍ਰੀ ਅਪਾਰ। ਰਿਝੀ ਸੁ ਧਾਰ। ੧੧।","roman":"Achhree apaar | rijhee su dhaar | 11 |","meaning_en":"countless apsaras were charmed in full.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":804,"lines":[{"gurmukhi":"ਗਾਵੰਤ ਗੀਤ। ਮੋਹੰਤ ਚੀਤ।","roman":"Gaavant geet | mohant cheet |","meaning_en":"They sang songs, enchanting the heart;","page":804,"meaning_status":"draft"},{"gurmukhi":"ਮਿਲਿ ਦੇ ਅਸੀਸ। ਜੁਗ ਚਾਰਿ ਜੀਸ। ੧੨।","roman":"Mili de asees | jug chaari jees | 12 |","meaning_en":"together they gave blessings: 'May you live through the four ages.'","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":804,"lines":[{"gurmukhi":"ਬਾਜੰਤ ਤਾਰ। ਡਾਰੈ ਧਮਾਰ।","roman":"Baajant taar | daarai dhamaar |","meaning_en":"Strings played, and they danced the dhamar;","page":804,"meaning_status":"draft","note":"ਡਾਰੈ ਧਮਾਰ: read as performing the dhamar (a Holi song/dance); uncertain."},{"gurmukhi":"ਦੇਵਾਨ ਨਾਰਿ। ਪੇਖਤ ਅਪਾਰ। ੧੩।","roman":"Devaan naari | pekhat apaar | 13 |","meaning_en":"countless wives of the gods looked on.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":804,"lines":[{"gurmukhi":"ਕੈ ਬੇਦ ਰੀਤਿ। ਗਾਵੰਤ ਗੀਤ।","roman":"Kai bed reeti | gaavant geet |","meaning_en":"Following the Vedic rite they sang songs;","page":804,"meaning_status":"draft"},{"gurmukhi":"ਸੋਭਾ ਅਨੂਪ। ਸੋਭੰਤ ਭੂਪ। ੧੪।","roman":"Sobhaa anoop | sobhant bhoop | 14 |","meaning_en":"of incomparable splendour, the kings shone.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[15],"number_text":"੧੫।","page":804,"lines":[{"gurmukhi":"ਬਾਜੰਤ ਤਾਰ। ਰੀਝੰਤ ਨਾਰਿ।","roman":"Baajant taar | reejhant naari |","meaning_en":"Strings played and women were charmed;","page":804,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵੰਤ ਗੀਤ। ਆਨੰਦ ਚੀਤਿ। ੧੫।","roman":"Gaavant geet | aanand cheeti | 15 |","meaning_en":"they sang songs with joy in their hearts.","page":804,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਉਛਾਲ ਛੰਦ","gurmukhi":"ਉਛਾਲ ਛੰਦ","roman":"Uchhaal chhand","meaning_en":"Uchhal metre.","page":804,"meaning_status":"draft"},{"type":"verse","number":[16],"number_text":"੧੬।","page":804,"lines":[{"gurmukhi":"ਗਾਵਤ ਨਾਰੀ। ਬਾਜਤ ਤਾਰੀ।","roman":"Gaavat naaree | baajat taaree |","meaning_en":"Women sang and clapping sounded;","page":804,"meaning_status":"draft","note":"ਤਾਰੀ: 'clapping' or 'strings'; uncertain."},{"gurmukhi":"ਦੇਖਤ ਰਾਜਾ। ਦੇਵਤ ਸਾਜਾ। ੧੬।","roman":"Dekhat raajaa | devat saajaa | 16 |","meaning_en":"the kings watched, giving away goods.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":804,"lines":[{"gurmukhi":"ਗਾਵਤ ਗੀਤੰ। ਆਨੰਦ ਚੀਤੰ।","roman":"Gaavat geetan | aanand cheetan |","meaning_en":"They sang songs with joy in their hearts;","page":804,"meaning_status":"draft"},{"gurmukhi":"ਸੋਭਤ ਸੋਭਾ। ਲੋਭਤ ਲੋਭਾ। ੧੭।","roman":"Sobhat sobhaa | lobhat lobhaa | 17 |","meaning_en":"splendour shone and desire was stirred.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[18],"number_text":"੧੮।","page":804,"lines":[{"gurmukhi":"ਦੇਖਤ ਨੈਣੰ। ਭਾਖਤ ਬੈਣੰ।","roman":"Dekhat nainan | bhaakhat bainan |","meaning_en":"Eyes gazed and words were spoken;","page":804,"meaning_status":"draft"},{"gurmukhi":"ਸੋਹਤ ਛਤ੍ਰੀ। ਲੋਭਤ ਅਤ੍ਰੀ। ੧੮।","roman":"Sohat chhatree | lobhat atree | 18 |","meaning_en":"the Kshatriyas shone and the weapon-bearers were tempted.","page":804,"meaning_status":"draft","note":"ਅਤ੍ਰੀ: 'weapon-bearers'; uncertain."}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":804,"lines":[{"gurmukhi":"ਗਜਤ ਹਾਥੀ। ਸਜਤ ਸਾਥੀ।","roman":"Gajat haathee | sajat saathee |","meaning_en":"Elephants trumpeted; companions were adorned;","page":804,"meaning_status":"draft"},{"gurmukhi":"ਕੂਦਤ ਬਾਜੀ। ਨਾਚਤ ਤਾਜੀ। ੧੯।","roman":"Koodat baajee | naachat taajee | 19 |","meaning_en":"horses leapt and steeds pranced.","page":804,"meaning_status":"draft","note":"ਤਾਜੀ: Persian, an Arab horse."}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":804,"lines":[{"gurmukhi":"ਬਾਜਤ ਤਾਲੰ। ਨਾਚਤ ਬਾਲੰ।","roman":"Baajat taalan | naachat baalan |","meaning_en":"Rhythms sounded and young women danced;","page":804,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਗਾਥੰ। ਆਨੰਦ ਸਾਥੰ। ੨੦।","roman":"Gaavat gaathan | aanand saathan | 20 |","meaning_en":"they sang ballads with joy.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":804,"lines":[{"gurmukhi":"ਕੋਕਿਲ ਬੈਣੀ। ਸੁੰਦਰ ਨੈਣੀ।","roman":"Kokil bainee | sundar nainee |","meaning_en":"With voices like the cuckoo and beautiful eyes,","page":804,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਗੀਤੰ। ਚੋਰਤ ਚੀਤੰ। ੨੧।","roman":"Gaavat geetan | chorat cheetan | 21 |","meaning_en":"they sang songs that stole the heart.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":804,"lines":[{"gurmukhi":"ਅਛ੍ਰਣ ਭੇਸੀ। ਸੁੰਦਰ ਕੇਸੀ।","roman":"Achhran bhesee | sundar kesee |","meaning_en":"Dressed like apsaras, with beautiful hair,","page":804,"meaning_status":"draft"},{"gurmukhi":"ਸੁੰਦਰ ਨੈਣੀ। ਕੋਕਿਲ ਬੈਣੀ। ੨੨।","roman":"Sundar nainee | kokil bainee | 22 |","meaning_en":"beautiful eyes and voices like the cuckoo,","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":804,"lines":[{"gurmukhi":"ਅਦਭੁਤ ਰੂਪਾ। ਕਾਮਿਣ ਕੂਪਾ।","roman":"Adbhut roopaa | kaamin koopaa |","meaning_en":"of wondrous form, wells of desire,","page":804,"meaning_status":"draft"},{"gurmukhi":"ਚਾਰੁ ਪ੍ਰਹਾਸੰ। ਉਨਤਿ ਨਾਸੰ। ੨੩।","roman":"Chaaru prahaasan | unti naasan | 23 |","meaning_en":"with lovely smiles and fine high noses.","page":804,"meaning_status":"draft"}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":805,"lines":[{"gurmukhi":"ਲਖਿ ਦੁਤਿ ਰਾਣੀ। ਲਜਿਤ ਇੰਦ੍ਰਾਣੀ।","roman":"Lakhi duti raanee | lajit indraanee |","meaning_en":"Seeing the princess's radiance, Indra's queen was ashamed;","page":805,"meaning_status":"draft","note":"ਰਾਣੀ: read as the princess (or 'the queens'); uncertain."},{"gurmukhi":"ਸੋਹਤ ਬਾਲਾ। ਰਾਗਣ ਮਾਲਾ। ੨੪।","roman":"Sohat baalaa | raagan maalaa | 24 |","meaning_en":"the maiden shone like a garland of melodies (raginis).","page":805,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਮੋਹਣੀ ਛੰਦ","gurmukhi":"ਮੋਹਣੀ ਛੰਦ","roman":"Mohnee chhand","meaning_en":"Mohani metre.","page":805,"meaning_status":"draft"},{"type":"verse","number":[25],"number_text":"੨੫।","page":805,"lines":[{"gurmukhi":"ਗਉਰ ਸਰੂਪ ਮਹਾ ਛਬਿ ਸੋਹਤ। ਦੇਖਤ ਸੁਰ ਨਰ ਕੋ ਮਨ ਮੋਹਤ।","roman":"Gaur saroop mahaa chhabi sohat | dekhat sur nar ko man mohat |","meaning_en":"Fair of form, she shone with great beauty; seeing her, the minds of gods and men were enchanted.","page":805,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝਤ ਤਾਕਿ ਬਡੇ ਨ੍ਰਿਪ ਐਸੇ। ਸੋਭਹਿੰ ਕਉਨ ਸਕੈ ਕਹਿ ਤੈਸੇ। ੨੫।","roman":"Reejhat taaki bade nrip aise | sobhhin kaun sakai kahi taise | 25 |","meaning_en":"Great kings, gazing at her, were so charmed; who could describe such splendour?","page":805,"meaning_status":"draft"}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":805,"lines":[{"gurmukhi":"ਸੁੰਦਰ ਰੂਪ ਮਹਾ ਦੁਤਿ ਬਾਲੀਯ। ਪੇਖਤ ਰੀਝਤ ਬੀਰ ਰਸਾਲੀਯ।","roman":"Sundar roop mahaa duti baaleey | pekhat reejhat beer rasaaleey |","meaning_en":"The maiden was beautiful and of great radiance; heroes, seeing her, were charmed by her grace.","page":805,"meaning_status":"draft"},{"gurmukhi":"ਨਾਚਤ ਭਾਵ ਅਨੇਕ ਤ੍ਰੀਆ ਕਰਿ। ਦੇਖਤ ਸੋਭਾ ਰੀਝਤ ਸੁਰ ਨਰ। ੨੬।","roman":"Naachat bhaav anek treeaa kari | dekhat sobhaa reejhat sur nar | 26 |","meaning_en":"The women danced with many expressions; seeing the splendour, gods and men were charmed.","page":805,"meaning_status":"draft"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":805,"lines":[{"gurmukhi":"ਹਿੰਸਤ ਹੈਵਰ ਚਿੰਸਤ ਹਾਥੀ। ਨਾਚਤ ਨਾਗਰਿ ਗਾਵਤ ਗਾਥੀ।","roman":"Hinsat haivar chinsat haathee | naachat naagri gaavat gaathee |","meaning_en":"Fine horses neighed and elephants trumpeted; city women danced and sang ballads.","page":805,"meaning_status":"draft","note":"ਚਿੰਸਤ: read as elephant's cry; uncertain."},{"gurmukhi":"ਰੀਝਤ ਸੁਰ ਨਰ ਮੋਹਤ ਰਾਜਾ। ਦੇਵਤ ਦਾਨ ਤੁਰੰਤ ਸਮਾਜਾ। ੨੭।","roman":"Reejhat sur nar mohat raajaa | devat daan turant samaajaa | 27 |","meaning_en":"Gods and men were charmed and kings enchanted; at once they gave away gifts and goods.","page":805,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":805,"lines":[{"gurmukhi":"ਗਾਵਤ ਗੀਤਨ ਨਾਚਤ ਅਪਛਰਾ। ਰੀਝਤ ਰਾਜਾ ਖੀਝਤ ਅਛਰਾ।","roman":"Gaavat geetan naachat apachhraa | reejhat raajaa kheejhat achhraa |","meaning_en":"The apsaras sang songs and danced; the kings were charmed, and (other) apsaras grew jealous.","page":805,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜਤ ਨਾਰਦ ਬੀਨ ਰਸਾਲੀ। ਦੇਖਤ ਦੇਵ ਪ੍ਰਭਾਸਤ ਜ੍ਵਾਲੀ। ੨੮।","roman":"Baajat naarad been rasaalee | dekhat dev prabhaasat jvaalee | 28 |","meaning_en":"Narad played his sweet vina; the gods looked on, shining like flame.","page":805,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":805,"lines":[{"gurmukhi":"ਆਂਜਤ ਅੰਜਨ ਸਾਜਤ ਅੰਗਾ। ਸੋਭਤ ਬਸਤ੍ਰ ਸੁ ਅੰਗ ਸੁਰੰਗਾ।","roman":"Aanjat anjan saajat angaa | sobhat basatr su ang surangaa |","meaning_en":"Applying collyrium and adorning their limbs, with fine bright garments shining on their bodies,","page":805,"meaning_status":"draft"},{"gurmukhi":"ਨਾਚਤ ਅਛ੍ਰੀ ਰੀਝਤ ਰਾਊ। ਚਾਹਤ ਬਰਬੋ ਕਰਤ ਉਪਾਊ। ੨੯।","roman":"Naachat achhree reejhat raaoo | chaahat barbo karat upaaoo | 29 |","meaning_en":"the apsaras danced and the kings were charmed; they wished to marry (her) and devised means.","page":805,"meaning_status":"draft","note":"Who wishes to marry whom is unclear; read as the kings wishing to wed the princess."}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":805,"lines":[{"gurmukhi":"ਤਤ ਥਈ ਨਾਚੈ ਸੁਰ ਪੁਰ ਬਾਲਾ। ਰੁਣ ਝੁਣ ਬਾਜੈ ਰੰਗ ਅੰਗ ਮਾਲਾ।","roman":"Tat thaee naachai sur pur baalaa | run jhun baajai rang ang maalaa |","meaning_en":"'Tat thai', the maidens of the city of gods danced; 'run jhun' rang the bright garlands on their limbs.","page":805,"meaning_status":"draft","note":"ਤਤ ਥਈ, ਰੁਣ ਝੁਣ: sound-words, left untranslated."},{"gurmukhi":"ਬਨਿ ਬਨਿ ਬੈਠੇ ਜਹ ਤਹ ਰਾਜਾ। ਦੈ ਦੈ ਡਾਰੈ ਤਨ ਮਨ ਸਾਜਾ। ੩੦।","roman":"Bani bani baithe jah tah raajaa | dai dai daarai tan man saajaa | 30 |","meaning_en":"Here and there the kings sat adorned, offering up body, mind and goods.","page":805,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":805,"lines":[{"gurmukhi":"ਜਿਹ ਜਿਹ ਦੇਖਾ ਸੋ ਸੋ ਰੀਝਾ। ਜਿਨ ਨਹੀ ਦੇਖਾ ਤਿਹ ਮਨ ਖੀਝਾ।","roman":"Jih jih dekhaa so so reejhaa | jin nahee dekhaa tih man kheejhaa |","meaning_en":"Whoever saw was charmed; whoever did not see was vexed in mind.","page":805,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਕਰਿ ਭਾਯੰ ਤ੍ਰੀਅ ਬਰ ਨਾਚੈ। ਅਤਿਭੁਤਿ ਭਾਯੰ ਅੰਗ ਅੰਗ ਰਾਚੈ। ੩੧।","roman":"Kari kari bhaayan treea bar naachai | atibhuti bhaayan ang ang raachai | 31 |","meaning_en":"Making expressions, the fine women danced; wondrous feeling was absorbed in every limb.","page":805,"meaning_status":"draft"}]},{"type":"verse","number":[32],"number_text":"੩੨।","page":805,"lines":[{"gurmukhi":"ਤਿਨ ਅਤਿਭੁਤਿ ਗਤਿ ਤਹ ਜਹ ਠਾਨੀ। ਜਹ ਤਹ ਸੋਹੈ ਮੁਨਿ ਮਨਿ ਮਾਨੀ।","roman":"Tin atibhuti gati tah jah thaanee | jah tah sohai muni mani maanee |","meaning_en":"They performed wondrous movements here and there; everywhere they shone, honoured by the minds of the sages.","page":805,"meaning_status":"draft"},{"gurmukhi":"ਤਜਿ ਤਜਿ ਜੋਗੰ ਭਜਿ ਭਜਿ ਆਵੈ। ਲਖਿ ਅਤਿ ਆਭਾ ਜੀਅ ਸੁਖ ਪਾਵੈ। ੩੨।","roman":"Taji taji jogan bhaji bhaji aavai | lakhi ati aabhaa jeea sukh paavai | 32 |","meaning_en":"Abandoning their yoga, (sages) came running; seeing the great radiance, their hearts found joy.","page":805,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":806,"lines":[{"gurmukhi":"ਬਨਿ ਬਨਿ ਬੈਠੇ ਜਹ ਤਹ ਰਾਜਾ। ਜਹ ਤਹ ਸੋਭੈ ਸਭ ਸੁਭ ਸਾਜਾ।","roman":"Bani bani baithe jah tah raajaa | jah tah sobhai sabh subh saajaa |","meaning_en":"Here and there the kings sat adorned; everywhere all fine array shone.","page":806,"meaning_status":"draft"},{"gurmukhi":"ਜਹ ਤਹ ਦੇਖੈ ਗੁਨਿ ਗਨ ਫੂਲੇ। ਮੁਨਿ ਮਨਿ ਛਬਿ ਲਖਿ ਤਨ ਮਨ ਭੂਲੇ। ੩੩।","roman":"Jah tah dekhai guni gan phoole | muni mani chhabi lakhi tan man bhoole | 33 |","meaning_en":"Wherever they looked, men of merit were delighted; the minds of sages, seeing the beauty, forgot body and mind.","page":806,"meaning_status":"draft"}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":806,"lines":[{"gurmukhi":"ਤਤ ਬਿਤ ਘਨ ਮੁਖਰਸ ਸਬ ਬਾਜੈ। ਸੁਨਿ ਮਨ ਰਾਗੰ ਗੁਨਿ ਗਨ ਲਾਜੈ।","roman":"Tat bit ghan mukhras sab baajai | suni man raagan guni gan laajai |","meaning_en":"Stringed, open, solid and wind instruments all played; hearing the melodies, men of merit were abashed.","page":806,"meaning_status":"draft","note":"ਤਤ ਬਿਤ ਘਨ ਮੁਖਰਸ: the four classes of instruments (stringed, membrane, solid, wind); uncertain on ਬਿਤ."},{"gurmukhi":"ਜਹ ਤਹ ਗਿਰ ਗੇ ਰਿਝਿ ਰਿਝਿ ਐਸੇ। ਜਨੁ ਭਟ ਜੂਝੇ ਰਣ ਬ੍ਰਿਣ ਕੈਸੇ। ੩੪।","roman":"Jah tah gir ge rijhi rijhi aise | janu bhat joojhe ran brin kaise | 34 |","meaning_en":"Here and there people fell, charmed, as warriors fall wounded in battle.","page":806,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":806,"lines":[{"gurmukhi":"ਬਨਿ ਬਨਿ ਫੂਲੇ ਜਨੁ ਬਰ ਫੂਲੰ। ਤਨੁ ਬਰੁ ਸੋਭੇ ਜਨੁ ਧਰ ਮੂਲੰ।","roman":"Bani bani phoole janu bar phoolan | tanu baru sobhe janu dhar moolan |","meaning_en":"Adorned, they bloomed like fine flowers; their fine bodies shone as if (rooted) in the earth.","page":806,"meaning_status":"draft","note":"ਧਰ ਮੂਲੰ: read as 'rooted in the earth'; uncertain."},{"gurmukhi":"ਜਹੰ ਤਹੰ ਝੂਲੇ ਮਦ ਮਤ ਰਾਜਾ। ਜਨੁ ਮੁਰਿ ਬੋਲੈ ਸੁਨ ਘਨ ਗਾਜਾ। ੩੫।","roman":"Jahan tahan jhoole mad mat raajaa | janu muri bolai sun ghan gaajaa | 35 |","meaning_en":"Here and there kings swayed, drunk with intoxication, like peacocks calling on hearing the thunder of clouds.","page":806,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਪਾਧਰੀ ਛੰਦ","gurmukhi":"ਪਾਧਰੀ ਛੰਦ","roman":"Paadhree chhand","meaning_en":"Padhri metre.","page":806,"meaning_status":"draft"},{"type":"verse","number":[36],"number_text":"੩੬।","page":806,"lines":[{"gurmukhi":"ਜਹ ਤਹ ਬਿਲੋਕਿ ਸੋਭਾ ਅਪਾਰ। ਬਨਿ ਬੈਠਿ ਸਰਬ ਰਾਜਾਧਿਕਾਰ।","roman":"Jah tah biloki sobhaa apaar | bani baithi sarab raajaadhikaar |","meaning_en":"Wherever one looked there was boundless splendour; all the sovereigns sat adorned.","page":806,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਭਾਤਿ ਕਹੈ ਨਹੀ ਪਰਤ ਬੈਨ। ਲਖਿ ਨੈਨ ਰੂਪਿ ਰੀਝੰਤ ਨੈਨ। ੩੬।","roman":"Ih bhaati kahai nahee parat bain | lakhi nain roopi reejhant nain | 36 |","meaning_en":"It cannot be put into words this way; seeing the beauty of eyes, eyes were charmed.","page":806,"meaning_status":"draft"}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":806,"lines":[{"gurmukhi":"ਅਵਿਲੋਕਿ ਨਾਚਿ ਐਸੋ ਸੁਰੰਗ। ਸਰ ਤਾਨਿ ਨ੍ਰਿਪਨ ਮਾਰਤ ਅਨੰਗ।","roman":"Aviloki naachi aiso surang | sar taani nripan maarat anang |","meaning_en":"Seeing such a colourful dance, Kama drew his arrows and shot the kings.","page":806,"meaning_status":"draft","note":"ਅਨੰਗ: 'the bodiless one', Kama, god of love."},{"gurmukhi":"ਸੋਭਾ ਅਪਾਰ ਬਰਣੀ ਨ ਜਾਇ। ਰੀਝੇ ਅਵਿਲੋਕਿ ਰਾਨਾ ਰੁ ਰਾਇ। ੩੭।","roman":"Sobhaa apaar barnee na jaai | reejhe aviloki raanaa ru raai | 37 |","meaning_en":"The boundless splendour cannot be described; seeing it, ranas and rajas were charmed.","page":806,"meaning_status":"draft"}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":806,"lines":[{"gurmukhi":"ਆਗਮ ਬਸੰਤ ਜਨੁ ਭਇਓ ਆਜ। ਇਹ ਭਾਤਿ ਸਰਬ ਦੇਖੈ ਸਮਾਜ।","roman":"Aagam basant janu bhaio aaj | ih bhaati sarab dekhai samaaj |","meaning_en":"It was as if spring had arrived today; in this way all saw the assembly.","page":806,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਾਧਿਰਾਜ ਬਨਿ ਬੈਠ ਐਸ। ਤਿਨ ਕੇ ਸਮਾਨ ਨਹੀ ਇੰਦ੍ਰ ਹੈਸ। ੩੮।","roman":"Raajaadhiraaj bani baith ais | tin ke samaan nahee indr hais | 38 |","meaning_en":"The supreme kings sat so adorned that even Indra was not equal to them.","page":806,"meaning_status":"draft","note":"ਹੈਸ: printed so; read as 'hai'/'is'; uncertain."}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":806,"lines":[{"gurmukhi":"ਇਕ ਮਾਸ ਲਾਗ ਤਹ ਭਇਓ ਨਾਚ। ਬਿਨ ਪੀਐ ਕੈਫ ਕੋਊ ਨ ਬਾਚ।","roman":"Ik maas laag tah bhaio naach | bin peeai kaiph ko'oo na baach |","meaning_en":"For a month there was dancing there; no one was left who had not drunk intoxicant.","page":806,"meaning_status":"draft","note":"ਕੈਫ: Arabic/Persian 'intoxication'."},{"gurmukhi":"ਜਹ ਜਹ ਬਿਲੋਕਿ ਆਭਾ ਅਪਾਰ। ਤਹ ਤਹ ਸੁ ਰਾਜ ਰਾਜਨ ਕੁਮਾਰ। ੩੯।","roman":"Jah jah biloki aabhaa apaar | tah tah su raaj raajan kumaar | 39 |","meaning_en":"Wherever one looked there was boundless splendour; there were the kings and princes.","page":806,"meaning_status":"draft"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":806,"lines":[{"gurmukhi":"ਲੈ ਸੰਗ ਤਾਸ ਸਾਰਸ੍ਵਤਿ ਆਪ। ਜਿਹ ਕੋ ਜਪੰਤ ਸਭ ਜਗਤ ਜਾਪ।","roman":"Lai sang taas saarsvati aap | jih ko japant sabh jagat jaap |","meaning_en":"Sarasvati herself, whose name all the world repeats, took her (the princess) along:","page":806,"meaning_status":"draft"},{"gurmukhi":"ਨਿਰਖੋ ਕੁਮਾਰ ਇਹ ਸਿੰਧ ਰਾਜ। ਜਾ ਕੀ ਸਮਾਨ ਨਹੀ ਇੰਦ੍ਰ ਸਾਜ। ੪੦।","roman":"Nirkho kumaar ih sindh raaj | jaa kee samaan nahee indr saaj | 40 |","meaning_en":"'Look, princess, this is the king of Sindh, whose splendour even Indra does not equal.'","page":806,"meaning_status":"draft"}]},{"type":"verse","number":[41],"number_text":"੪੧।","page":806,"lines":[{"gurmukhi":"ਅਵਿਲੋਕ ਸਿੰਧ ਰਾਜਾ ਕੁਮਾਰ। ਨਹੀ ਤਾਸ ਚਿਤ ਕਿਨੋ ਸਮੁਾਰ।","roman":"Avilok sindh raajaa kumaar | nahee taas chit kino samaar |","meaning_en":"The princess looked at the king of Sindh, but did not take him into her heart.","page":806,"meaning_status":"draft","note":"ਸਮੁਾਰ: printed so; read as ਸੰਭਾਰ, 'regard'."},{"gurmukhi":"ਤਿਹ ਛਾਡਿ ਪਾਛ ਆਗੈ ਚਲੀਸੁ। ਜਨੁ ਸਰਬ ਸੋਭ ਕਹੁ ਲੀਲ ਲੀਸੁ। ੪੧।","roman":"Tih chhaadi paachh aagai chaleesu | janu sarab sobh kahu leel leesu | 41 |","meaning_en":"Leaving him behind, she moved on, as if she had swallowed up all splendour.","page":806,"meaning_status":"draft"}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":806,"lines":[{"gurmukhi":"ਪੁਨਿ ਕਹੈ ਤਾਸ ਸਾਰਸ੍ਵਤੀ ਬੈਨ। ਇਹ ਪਸਚਮੇਸ ਅਬ ਦੇਖ ਨੈਨਿ।","roman":"Puni kahai taas saarsvatee bain | ih pasachmes ab dekh naini |","meaning_en":"Then Sarasvati spoke to her: 'Now see with your eyes this lord of the west.'","page":806,"meaning_status":"draft"},{"gurmukhi":"ਅਵਿਲੋਕਿ ਰੂਪ ਤਾ ਕੋ ਅਪਾਰ। ਨਹੀ ਮਧਿ ਚਿਤਿ ਆਨਿਓ ਕੁਮਾਰ। ੪੨।","roman":"Aviloki roop taa ko apaar | nahee madhi chiti aanio kumaar | 42 |","meaning_en":"Seeing his boundless beauty, the princess did not bring him into her heart.","page":806,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਮਧੁਭਾਰ ਛੰਦ","gurmukhi":"ਮਧੁਭਾਰ ਛੰਦ","roman":"Madhubhaar chhand","meaning_en":"Madhubhar metre.","page":807,"meaning_status":"draft"},{"type":"verse","number":[43],"number_text":"੪੩।","page":807,"lines":[{"gurmukhi":"ਦੇਖੋ ਕੁਮਾਰ। ਰਾਜਾ ਜੁਝਾਰ।","roman":"Dekho kumaar | raajaa jujhaar |","meaning_en":"'Look, princess, at this warrior king,","page":807,"meaning_status":"draft"},{"gurmukhi":"ਸੁਭ ਵਾਰ ਦੇਸ। ਸੁੰਦਰ ਸੁਬੇਸ। ੪੩।","roman":"Subh vaar des | sundar subes | 43 |","meaning_en":"of a fine land, handsome and well dressed.'","page":807,"meaning_status":"draft","note":"ਸੁਭ ਵਾਰ ਦੇਸ: read as 'of a fine land'; uncertain."}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":807,"lines":[{"gurmukhi":"ਦੇਖਿਓ ਬਿਚਾਰ। ਰਾਜਾ ਅਪਾਰ।","roman":"Dekhio bichaar | raajaa apaar |","meaning_en":"She looked thoughtfully at the boundless king,","page":807,"meaning_status":"draft"},{"gurmukhi":"ਆਨਾ ਨ ਚਿਤ। ਪਰਮੰ ਪਵਿਤ। ੪੪।","roman":"Aanaa na chit | parman pavit | 44 |","meaning_en":"but did not bring him into her heart, she who was supremely pure.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[45],"number_text":"੪੫।","page":807,"lines":[{"gurmukhi":"ਤਬ ਆਗਿ ਚਾਲ। ਸੁੰਦਰ ਸੁ ਬਾਲ।","roman":"Tab aagi chaal | sundar su baal |","meaning_en":"Then the beautiful maiden moved on,","page":807,"meaning_status":"draft"},{"gurmukhi":"ਮੁਸਕਿਆਤ ਐਸ। ਘਨਿ ਬੀਜ ਜੈਸ। ੪੫।","roman":"Muskiaat ais | ghani beej jais | 45 |","meaning_en":"smiling like lightning in the clouds.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[46],"number_text":"੪੬।","page":807,"lines":[{"gurmukhi":"ਨ੍ਰਿਪ ਪੇਖਿ ਰੀਝ। ਸੁਰ ਨਾਰ ਖੀਝ।","roman":"Nrip pekhi reejh | sur naar kheejh |","meaning_en":"The kings, seeing her, were charmed; the women of the gods were vexed,","page":807,"meaning_status":"draft"},{"gurmukhi":"ਬਢਿ ਤਾਸ ਜਾਨ। ਘਟ ਆਪ ਮਾਨ। ੪੬।","roman":"Badhi taas jaan | ghat aap maan | 46 |","meaning_en":"knowing her to be greater, and themselves lesser.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":807,"lines":[{"gurmukhi":"ਸੁੰਦਰ ਸਰੂਪ। ਸੌਦਰਜੁ ਭੂਪ।","roman":"Sundar saroop | saudarju bhoop |","meaning_en":"'Of beautiful form is this king of beauty,","page":807,"meaning_status":"draft","note":"ਸੌਦਰਜੁ: printed so; read as 'saundarya', beauty."},{"gurmukhi":"ਸੋਭਾ ਅਪਾਰ। ਸੋਭੈ ਸੁ ਧਾਰ। ੪੭।","roman":"Sobhaa apaar | sobhai su dhaar | 47 |","meaning_en":"of boundless glory, shining finely.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":807,"lines":[{"gurmukhi":"ਦੇਖੋ ਨਰੇਂਦ੍ਰ। ਡਾਢੇ ਮਹੇਂਦ੍ਰ।","roman":"Dekho narendr | daadhe mahendr |","meaning_en":"Look at this lord of men, mighty as great Indra,","page":807,"meaning_status":"draft","note":"ਡਾਢੇ: 'mighty'; uncertain."},{"gurmukhi":"ਮੁਲਤਾਨ ਰਾਜ। ਰਾਜਾਨ ਰਾਜ। ੪੮।","roman":"Multaan raaj | raajaan raaj | 48 |","meaning_en":"king of Multan, king among kings.'","page":807,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Bhujang prayaat chhand","meaning_en":"Bhujang Prayat metre.","page":807,"meaning_status":"draft"},{"type":"verse","number":[49],"number_text":"੪੯।","page":807,"lines":[{"gurmukhi":"ਚਲੀ ਛੋਡਿ ਤਾ ਕੌ ਤ੍ਰੀਆ ਰਾਜ ਐਸੇ। ਮਨੋ ਪਾਂਡੁ ਪੁਤ੍ਰੰ ਸਿਰੀ ਰਾਜ ਜੈਸੇ।","roman":"Chalee chhodi taa kau treeaa raaj aise | mano paandu putran siree raaj jaise |","meaning_en":"The royal maiden left him and moved on, like royal splendour (leaving) the sons of Pandu.","page":807,"meaning_status":"draft","note":"Simile uncertain."},{"gurmukhi":"ਖਰੀ ਮਧਿ ਰਾਜਿਸਥਲੀ ਐਸ ਸੋਹੈ। ਮਨੋ ਜ੍ਵਾਲ ਮਾਲਾ ਮਹਾ ਮੋਨਿ ਮੋਹੈ। ੪੯।","roman":"Kharee madhi raajisathlee ais sohai | mano jvaal maalaa mahaa moni mohai | 49 |","meaning_en":"Standing in the midst of the royal arena she shone, as if a garland of flame enchanted even great silent sages.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":807,"lines":[{"gurmukhi":"ਸੁਭੇ ਰਾਜਿਸਥਲੀ ਠਾਢਿ ਐਸੇ। ਮਨੋ ਚਿਤ੍ਰਕਾਰੀ ਲਿਖੀ ਚਿਤ੍ਰ ਜੈਸੇ।","roman":"Subhe raajisathlee thaadhi aise | mano chitrakaaree likhee chitr jaise |","meaning_en":"She stood shining in the royal arena, as if a painter had painted a picture.","page":807,"meaning_status":"draft"},{"gurmukhi":"ਬਧੇ ਸ੍ਵਰਣ ਕੀ ਕਿੰਕਣੀ ਲਾਲ ਮਾਲੰ। ਸਿਖਾ ਜਾਨ ਸੋਭੇ ਨ੍ਰਿਪੰ ਜਗਿ ਜ੍ਵਾਲੰ। ੫੦।","roman":"Badhe svaran kee kinknee laal maalan | sikhaa jaan sobhe nripan jagi jvaalan | 50 |","meaning_en":"She wore a girdle of golden bells and a garland of rubies; she shone like the flame of the kings' sacrificial fire.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[51],"number_text":"੫੧।","page":807,"lines":[{"gurmukhi":"ਕਹੇ ਬੈਨ ਸਾਰਸ੍ਵਤੀ ਪੇਖਿ ਬਾਲਾ। ਲਖੋ ਨੈਨਿ ਠਾਢੇ ਸਭੈ ਭੂਪ ਆਲਾ।","roman":"Kahe bain saarsvatee pekhi baalaa | lakho naini thaadhe sabhai bhoop aalaa |","meaning_en":"Sarasvati, looking at the maiden, spoke: 'See with your eyes all the noble kings standing here.","page":807,"meaning_status":"draft","note":"ਆਲਾ: Arabic/Persian 'ala', high/noble."},{"gurmukhi":"ਰੁਚੈ ਚਿਤ ਜਉਨੈ ਸੁਈ ਨਾਥ ਕੀਜੈ। ਸੁਨੋ ਪ੍ਰਾਨ ਪਿਆਰੀ ਇਹੈ ਮਾਨਿ ਲੀਜੈ। ੫੧।","roman":"Ruchai chit jaunai suee naath keejai | suno praan piaaree ihai maani leejai | 51 |","meaning_en":"Whomever your heart likes, make him your lord; listen, darling of my life, accept this.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":807,"lines":[{"gurmukhi":"ਬਡੀ ਬਾਹਨੀ ਸੰਗਿ ਜਾ ਕੇ ਬਿਰਾਜੈ। ਘੁਰੈ ਸੰਗ ਭੇਰੀ ਮਹਾ ਨਾਦ ਬਾਜੈ।","roman":"Badee baahnee sangi jaa ke biraajai | ghurai sang bheree mahaa naad baajai |","meaning_en":"He with whom a great army shines, with whom kettledrums thunder and great sounds play,","page":807,"meaning_status":"draft"},{"gurmukhi":"ਲਖੋ ਰੂਪ ਬੇਸੰ ਮਹਾਨੰ। ਦਿਨੰ ਰੈਣ ਜਾਪੈ ਸਹੰਸ੍ਰ ਭੁਜਾਨੰ। ੫੨।","roman":"Lakho roop besan mahaanan | dinan rain jaapai sahansr bhujaanan | 52 |","meaning_en":"see his form and great attire; day and night he worships the thousand-armed (Lord).","page":807,"meaning_status":"draft","note":"Line short in print; ਸਹੰਸ੍ਰ ਭੁਜਾਨੰ: 'the thousand-armed', a name of the Divine; uncertain."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":807,"lines":[{"gurmukhi":"ਧੁਜਾ ਮਧਿ ਜਾ ਕੇ ਬਡੋ ਸਿੰਘ ਰਾਜੈ। ਸੁਨੇ ਨਾਦ ਤਾ ਕੋ ਮਹਾ ਪਾਪ ਭਾਜੈ।","roman":"Dhujaa madhi jaa ke bado singh raajai | sune naad taa ko mahaa paap bhaajai |","meaning_en":"In the midst of whose banner a great lion shines, at the sound of whose (drum) great sins flee,","page":807,"meaning_status":"draft"},{"gurmukhi":"ਲਖੋ ਪੂਰਬੀਸੰ ਛਿਤੀਸੰ ਮਹਾਨੰ। ਸੁਨੋ ਬੈਨ ਬਾਲਾ ਸੁਰੂਪੰ ਸੁ ਭਾਨੰ। ੫੩।","roman":"Lakho poorbeesan chhiteesan mahaanan | suno bain baalaa suroopan su bhaanan | 53 |","meaning_en":"see him, the lord of the east, great lord of the earth; hear my words, O maiden, beautiful and radiant.","page":807,"meaning_status":"draft"}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":807,"lines":[{"gurmukhi":"ਘੁਰੈ ਦੁੰਦਭੀ ਸੰਖ ਭੇਰੀ ਅਪਾਰੰ। ਬਜੈ ਦਛਨੀ ਸਰਬ ਬਾਜੰਤ੍ਰ ਸਾਰੰ।","roman":"Ghurai dundbhee sankh bheree apaaran | bajai dachhnee sarab baajantr saaran |","meaning_en":"Countless kettledrums, conches and trumpets resound; all the fine instruments of the south play;","page":807,"meaning_status":"draft"},{"gurmukhi":"ਤੁਰੀ ਕਾਨਰੇ ਤੂਰ ਤਾਨੰ ਤਰੰਗੰ। ਮੁਚੰ ਝਾਝਰੰ ਨਾਇ ਨਾਦੰ ਮ੍ਰਿਦੰਗੰ। ੫੪।","roman":"Turee kaanre toor taanan tarangan | muchan jhaajhran naai naadan mridangan | 54 |","meaning_en":"trumpets, horns and bugles in waves of tune, jew's-harps, cymbals, nai and the sound of the mridang.","page":807,"meaning_status":"draft","note":"ਕਾਨਰੇ, ਨਾਇ: names of wind instruments; uncertain."}]},{"type":"verse","number":[55],"number_text":"੫੫।","page":808,"lines":[{"gurmukhi":"ਬਧੇ ਹੀਰ ਚੀਰੰ ਸੁ ਬੀਰੰ ਸੁਬਾਹੰ। ਬਡੋ ਛਤ੍ਰਧਾਰੀ ਸੋ ਸੋਭਿਓ ਸਿਪਾਹੰ।","roman":"Badhe heer cheeran su beeran subaahan | bado chhatradhaaree so sobhio sipaahan |","meaning_en":"Wearing diamonds and fine garments, the brave, long-armed one, a great canopied king, shines as a soldier;","page":808,"meaning_status":"draft"},{"gurmukhi":"ਨਹੇ ਪਿੰਗ ਬਾਜੀ ਰਥੰ ਜੇਣਿ ਜਾਨੋ। ਤਿਸੈ ਦਛਨੇਸੰ ਹੀਐ ਬਾਲ ਮਾਨੋ। ੫੫।","roman":"Nahe ping baajee rathan jeni jaano | tisai dachhnesan heeai baal maano | 55 |","meaning_en":"whose chariot you see yoked with tawny horses, take that lord of the south to heart, O maiden.","page":808,"meaning_status":"draft"}]},{"type":"verse","number":[56],"number_text":"੫੬।","page":808,"lines":[{"gurmukhi":"ਮਹਾ ਬਾਹਨੀਸੰ ਨਗੀਸੰ ਨਰੇਸੰ। ਕਈ ਕੇਟਿ ਪਾਤੰ ਸੁਭੈ ਪਤ੍ਰ ਭੇਸੰ।","roman":"Mahaa baahneesan nageesan naresan | kaee keti paatan subhai patr bhesan |","meaning_en":"Lord of a great army, lord of mountains, king of men, with many millions of followers shining in fine dress,","page":808,"meaning_status":"draft","note":"ਪਾਤੰ ... ਪਤ੍ਰ ਭੇਸੰ: uncertain."},{"gurmukhi":"ਧੁਜਾ ਬਧ ਉਧੰ ਗਜੰ ਗੂੜ ਬਾਂਕੋ। ਲਖੋ ਉਤਰੀ ਰਾਜ ਕੈ ਨਾਮ ਤਾ ਕੋ। ੫੬।","roman":"Dhujaa badh udhan gajan goor baanko | lakho utree raaj kai naam taa ko | 56 |","meaning_en":"with a banner raised high and an elephant hidden and splendid: know his name as the king of the north.","page":808,"meaning_status":"draft","note":"ਗਜੰ ਗੂੜ ਬਾਂਕੋ: uncertain."}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":808,"lines":[{"gurmukhi":"ਫਰੀ ਧੋਪ ਪਾਇਕ ਸੁ ਆਗੇ ਉਮੰਗੈ। ਜਿਣੈ ਕੋਟਿ ਬੰਕੈ ਮੁਰੇ ਨਾਹਿ ਅੰਗੈ।","roman":"Pharee dhop paaik su aage umangai | jinai koti bankai mure naahi angai |","meaning_en":"Shield-bearers, swordsmen and foot soldiers surge eagerly before him; they win millions of strong forts and do not turn their bodies away;","page":808,"meaning_status":"draft","note":"ਫਰੀ ਧੋਪ: 'shields and straight swords'."},{"gurmukhi":"ਹਰੇ ਬਾਜ ਰਾਜੰ ਕਪੋਤੰ ਪ੍ਰਮਾਨੰ। ਨਹੇ ਸ੍ਯੰਦਨੀ ਇੰਦ੍ਰ ਬਾਜੀ ਸਮਾਣੰ। ੫੭।","roman":"Hare baaj raajan kapotan pramaanan | nahe syandnee indr baajee samaanan | 57 |","meaning_en":"his royal horses are green like pigeons; his chariot is yoked with horses like Indra's.","page":808,"meaning_status":"draft","note":"ਹਰੇ: 'green/grey' or 'swift'; uncertain."}]},{"type":"verse","number":[58],"number_text":"੫੮।","page":808,"lines":[{"gurmukhi":"ਬਡੇ ਸ੍ਰਿੰਗ ਜਾ ਕੇ ਧਰੇ ਸੂਰ ਸੋਭੈ। ਲਖੇ ਦੈਤ ਕੰਨ੍ਯਾ ਜਿਨੈ ਚਿਤ ਲੋਭੈ।","roman":"Bade sring jaa ke dhare soor sobhai | lakhe dait kannyaa jinai chit lobhai |","meaning_en":"He with great horns, who shines like a hero, at the sight of whom the daughters of demons are tempted in mind,","page":808,"meaning_status":"draft"},{"gurmukhi":"ਕਢੇ ਦੰਤ ਪਤੰ ਸਿਰੰ ਕੇਸ ਉਚੰ। ਲਖੇ ਗਰਭਣੀ ਆਣਿ ਕੇ ਗਰਭ ਮੁਚੰ। ੫੮।","roman":"Kadhe dant patan siran kes uchan | lakhe garabhnee aani ke garabh muchan | 58 |","meaning_en":"with rows of protruding teeth and hair standing high on his head; seeing him, pregnant women miscarry.","page":808,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":808,"lines":[{"gurmukhi":"ਲਖੋ ਲੰਕ ਏਸੰ ਨਰੇਸੰ ਸੁ ਬਾਲੰ। ਸਬੈ ਸੰਗ ਜਾ ਕੈ ਸਬੈ ਲੋਕ ਪਾਲੰ।","roman":"Lakho lank esan naresan su baalan | sabai sang jaa kai sabai lok paalan |","meaning_en":"See, maiden, the lord of Lanka, king of men, with whom are all the guardians of the worlds;","page":808,"meaning_status":"draft","note":"ਸੁ ਬਾਲੰ: may be part of the name ('Bal') or address 'O maiden'; uncertain."},{"gurmukhi":"ਲੁਟਿਓ ਏਕ ਬੇਰੰ ਕੁਬੇਰੰ ਭੰਡਾਰੀ। ਜਿਣਿਓ ਇੰਦ੍ਰ ਰਾਜਾ ਬਡੋ ਛਤ੍ਰਧਾਰੀ। ੫੯।","roman":"Lutio ek beran kuberan bhandaaree | jinio indr raajaa bado chhatradhaaree | 59 |","meaning_en":"once he looted Kuber the treasurer and conquered King Indra, the great canopied one.'","page":808,"meaning_status":"draft","note":"Description fits Ravan; not named in the text."}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":808,"lines":[{"gurmukhi":"ਕਹੇ ਜਉਨ ਬਾਲੀ ਨ ਤੇ ਚਿਤ ਆਨੇ। ਜਿਤੇ ਭੂਪ ਭਾਰੀ ਸੁ ਪਾਛੇ ਬਖਾਨੇ।","roman":"Kahe jaun baalee na te chit aane | jite bhoop bhaaree su paachhe bakhaane |","meaning_en":"Those she named, the maiden did not take to heart, all the mighty kings described before.","page":808,"meaning_status":"draft"},{"gurmukhi":"ਚਹੁੰ ਓਰ ਰਾਜਾ ਕਹੋ ਨਾਮ ਸੋ ਭੀ। ਤਜੇ ਭਾਤਿ ਜੈਸੀ ਸਬੈ ਰਾਜ ਓ ਭੀ। ੬੦।","roman":"Chahun or raajaa kaho naam so bhee | taje bhaati jaisee sabai raaj o bhee | 60 |","meaning_en":"'I tell also the names of the kings of the four quarters'; but she left them all just as she had left the others.","page":808,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":808,"lines":[{"gurmukhi":"ਲਖੋ ਦਈਤ ਸੈਨਾ ਬਡੀ ਸੰਗਿ ਤਾ ਕੇ। ਸੁਭੈ ਛਤ੍ਰ ਧਾਰੀ ਬਡੇ ਸੰਗ ਜਾ ਕੇ।","roman":"Lakho daeet sainaa badee sangi taa ke | subhai chhatr dhaaree bade sang jaa ke |","meaning_en":"'See, with him is a great army of demons; great canopied kings shine with him;","page":808,"meaning_status":"draft","note":"ਦਈਤ: printed so; read as ਦੈਤ, demons."},{"gurmukhi":"ਧੁਜਾ ਗਿਧ ਉਧੰ ਲਸੈ ਕਾਕ ਪੂਰੰ। ਤਿਸੈ ਪਿਆਲ ਰਾਜਾ ਬਲੀ ਬ੍ਰਿਧ ਨੂਰੰ। ੬੧।","roman":"Dhujaa gidh udhan lasai kaak pooran | tisai piaal raajaa balee bridh nooran | 61 |","meaning_en":"his banner, raised high, shines with vultures and crows: that is the mighty king of the underworld, of great splendour.","page":808,"meaning_status":"draft","note":"ਪਿਆਲ: read as 'Patal' (underworld); ਨੂਰ: Persian/Arabic 'light'; uncertain."}]},{"type":"verse","number":[62],"number_text":"੬੨।","page":808,"lines":[{"gurmukhi":"ਰਥੰ ਬੇਸਟੰ ਹੀਰ ਚੀਰੰ ਅਪਾਰੰ। ਸੁਭੈ ਸੰਗ ਜਾ ਕੇ ਸਭੇ ਲੋਕ ਪਾਰੰ।","roman":"Rathan bestan heer cheeran apaaran | subhai sang jaa ke sabhe lok paaran |","meaning_en":"His chariot is wrapped in diamonds and countless fine cloths; with him shine all the guardians of the worlds.","page":808,"meaning_status":"draft","note":"ਲੋਕ ਪਾਰੰ: read as 'lokpal'; uncertain."},{"gurmukhi":"ਇਹੈ ਇੰਦ੍ਰ ਰਾਜਾ ਦੁਰੰ ਦਾਨਵਾਰੰ। ਤ੍ਰੀਆ ਤਾਸ ਚੀਨੋ ਅਦਿਤਿਆ ਕੁਮਾਰੰ। ੬੨।","roman":"Ihai indr raajaa duran daanvaaran | treeaa taas cheeno aditiaa kumaaran | 62 |","meaning_en":"This is King Indra, enemy of the demons; and O lady, recognise this one as the son of Aditi.","page":808,"meaning_status":"draft","note":"ਦੁਰੰ ਦਾਨਵਾਰੰ: read as 'foe of demons'; ਅਦਿਤਿਆ ਕੁਮਾਰੰ: the sun-god, son of Aditi; uncertain."}]},{"type":"verse","number":[63],"number_text":"੬੩।","page":808,"lines":[{"gurmukhi":"ਨਹੇ ਸਪਤ ਬਾਜੀ ਰਥੰ ਏਕ ਚਕ੍ਰੰ। ਮਹਾ ਨਾਗ ਬਧੰ ਤਪੈ ਤੇਜ ਬਕ੍ਰੰ।","roman":"Nahe sapat baajee rathan ek chakran | mahaa naag badhan tapai tej bakran |","meaning_en":"His one-wheeled chariot is yoked with seven horses, bound with a great serpent; he blazes with fierce radiance;","page":808,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਉਗ੍ਰ ਧੰਨ੍ਵਾ ਸੁ ਆਜਾਨ ਬਾਹੰ। ਸਹੀ ਚਿਤ ਚੀਨੋ ਤਿਸੈ ਦਿਉਸ ਨਾਹੰ। ੬੩।","roman":"Mahaa ugr dhannvaa su aajaan baahan | sahee chit cheeno tisai dius naahan | 63 |","meaning_en":"a fierce archer with arms reaching to his knees; know truly in your heart that he is the lord of the day.","page":808,"meaning_status":"draft"}]},{"type":"verse","number":[64],"number_text":"੬੪।","page":809,"lines":[{"gurmukhi":"ਚੜਿਓ ਏਣ ਰਾਜੰ ਧਰੇ ਬਾਣ ਪਾਣੰ। ਨਿਸਾ ਰਾਜ ਤਾ ਕੋ ਲਖੋ ਤੇਜ ਮਾਣੰ।","roman":"Chario en raajan dhare baan paanan | nisaa raaj taa ko lakho tej maanan |","meaning_en":"Riding on the king of deer, holding arrows in his hand: see the lord of the night, proud of his radiance.","page":809,"meaning_status":"draft","note":"The moon's mount is the deer."},{"gurmukhi":"ਕਰੈ ਰਸਮਿ ਮਾਲਾ ਉਜਾਲਾ ਪਰਾਨੰ। ਜਪੈ ਰਾਤ੍ਰ ਦਿਉਸੰ ਸਹੰਸ੍ਰੀ ਭੁਜਾਨੰ। ੬੪।","roman":"Karai rasmi maalaa ujaalaa paraanan | japai raatr diusan sahansree bhujaanan | 64 |","meaning_en":"His garland of rays gives light to all; night and day he worships the thousand-armed (Lord).","page":809,"meaning_status":"draft","note":"ਪਰਾਨੰ: read as 'to others/all'; uncertain."}]},{"type":"verse","number":[65],"number_text":"੬੫।","page":809,"lines":[{"gurmukhi":"ਚੜੇ ਮਹਿਖੀਸੰ ਸੁਮੇਰੰ ਜੁ ਦੀਸੰ। ਮਹਾ ਕ੍ਰੂਰ ਕਰਮੰ ਜਿਣਿਓ ਬਾਹ ਬੀਸੰ।","roman":"Chare mahikheesan sumeran ju deesan | mahaa kroor karman jinio baah beesan |","meaning_en":"He who rides the lord of buffaloes, who looks like Mount Sumer, of very cruel deeds, who conquered the twenty-armed one;","page":809,"meaning_status":"draft","note":"Description fits Yama (buffalo mount); 'twenty-armed' = Ravan; uncertain."},{"gurmukhi":"ਧੁਜਾ ਦੰਡ ਜਾ ਕੀ ਪ੍ਰਚੰਡੰ ਬਿਰਾਜੈ। ਲਖੇ ਜਾਸ ਗਰਬੀਨ ਕੋ ਗਰਬ ਭਾਜੈ। ੬੫।","roman":"Dhujaa dand jaa kee prachandan biraajai | lakhe jaas garbeen ko garab bhaajai | 65 |","meaning_en":"whose banner-staff shines fiercely; seeing whom, the pride of the proud runs away.","page":809,"meaning_status":"draft"}]},{"type":"verse","number":[66],"number_text":"੬੬।","page":809,"lines":[{"gurmukhi":"ਕਹਾ ਲੌ ਬਖਾਨੋ ਬਡੇ ਗਰਬਧਾਰੀ। ਸਬੈ ਘੇਰਿ ਠਾਢੇ ਜੁਰੀ ਭੀਰ ਭਾਰੀ।","roman":"Kahaa lau bakhaano bade garabdhaaree | sabai gheri thaadhe juree bheer bhaaree |","meaning_en":"How far can I describe the great proud ones? All stood around in a great gathered crowd;","page":809,"meaning_status":"draft"},{"gurmukhi":"ਨਚੈ ਪਾਤਰਾ ਚਾਤੁਰਾ ਨਿਰਤਕਾਰੀ। ਉਠੈ ਝਾਂਝ ਸਬਦੰ ਸੁਨੈ ਲੋਗ ਧਾਰੀ। ੬੬।","roman":"Nachai paatraa chaaturaa niratkaaree | uthai jhaanjh sabdan sunai log dhaaree | 66 |","meaning_en":"skilful dancing-girls danced; the sound of cymbals rose, and people listened.","page":809,"meaning_status":"draft"}]},{"type":"verse","number":[67],"number_text":"੬੭।","page":809,"lines":[{"gurmukhi":"ਬਡੋ ਦਿਰਬ ਧਾਰੀ ਬਡੀ ਸੈਨ ਲੀਨੇ। ਬਡੋ ਦਿਰਬ ਕੋ ਚਿਤ ਮੈ ਗਰਬ ਕੀਨੇ।","roman":"Bado dirab dhaaree badee sain leene | bado dirab ko chit mai garab keene |","meaning_en":"'He who holds great wealth and has brought a great army, and has made great pride in his heart of his wealth,","page":809,"meaning_status":"draft","note":"ਦਿਰਬ: read as 'dravya', wealth."},{"gurmukhi":"ਚਿਤੰ ਤਾਸ ਚੀਨੋ ਸਹੀ ਦਿਰਬ ਪਾਲੰ। ਉਠੈ ਜਉਨ ਕੇ ਰੂਪ ਕੀ ਜ੍ਵਾਲ ਮਾਲੰ। ੬੭।","roman":"Chitan taas cheeno sahee dirab paalan | uthai jaun ke roop kee jvaal maalan | 67 |","meaning_en":"know him truly in your heart as the guardian of wealth (Kuber), from whose form rise garlands of flame.'","page":809,"meaning_status":"draft"}]},{"type":"verse","number":[68],"number_text":"੬੮।","page":809,"lines":[{"gurmukhi":"ਸਭੈ ਭੂਪ ਠਾਢੇ ਜਹਾ ਰਾਜ ਕੰਨਿਆ। ਬਿਖੈ ਭੂ ਤਲੰ ਰੂਪ ਜਾ ਕੇ ਨ ਅੰਨਿਆ।","roman":"Sabhai bhoop thaadhe jahaa raaj kanniaa | bikhai bhoo talan roop jaa ke na anniaa |","meaning_en":"All the kings stood where the princess was, whose beauty had no equal on the surface of the earth.","page":809,"meaning_status":"draft"},{"gurmukhi":"ਬਡੇ ਛਤ੍ਰਧਾਰੀ ਬਡੇ ਗਰਬ ਕੀਨੇ। ਤਹਾ ਆਨਿ ਠਾਢੇ ਬਡੀ ਸੈਨ ਲੀਨੇ। ੬੮।","roman":"Bade chhatradhaaree bade garab keene | tahaa aani thaadhe badee sain leene | 68 |","meaning_en":"Great canopied kings, full of great pride, came and stood there with great armies.","page":809,"meaning_status":"draft"}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":809,"lines":[{"gurmukhi":"ਨਦੀ ਸੰਗ ਜਾ ਕੇ ਸਬੈ ਰੂਪ ਧਾਰੇ। ਸਬੈ ਸਿੰਧ ਸੰਗੰ ਚੜੇ ਤੇਜ ਵਾਰੇ।","roman":"Nadee sang jaa ke sabai roop dhaare | sabai sindh sangan chare tej vaare |","meaning_en":"He with whom all the rivers came in bodily form, with whom all the seas came, glorious,","page":809,"meaning_status":"draft"},{"gurmukhi":"ਬਡੀ ਕਾਇ ਜਾ ਕੀ ਮਹਾ ਰੂਪ ਸੋਹੈ। ਲਖੇ ਦੇਵ ਕੰਨਿਆਨ ਕੇ ਮਾਨ ਮੋਹੈ। ੬੯।","roman":"Badee kaai jaa kee mahaa roop sohai | lakhe dev kanniaan ke maan mohai | 69 |","meaning_en":"whose great body shines with great beauty, at the sight of whom the pride of the daughters of the gods is charmed away:","page":809,"meaning_status":"draft"}]},{"type":"verse","number":[70],"number_text":"੭੦।","page":809,"lines":[{"gurmukhi":"ਕਹੋ ਨਾਰ ਤੋ ਕੌ ਇਹੇ ਬਰੁਨ ਰਾਜਾ। ਜਿਸੈ ਪੇਖਿ ਰਾਜਾਨ ਕੋ ਮਾਨ ਭਾਜਾ।","roman":"Kaho naar to kau ihe barun raajaa | jisai pekhi raajaan ko maan bhaajaa |","meaning_en":"'I tell you, lady, this is King Varun, at the sight of whom the pride of kings runs away.'","page":809,"meaning_status":"draft"},{"gurmukhi":"ਕਹਾ ਲੌ ਬਖਾਨੋ ਜਿਤੇ ਭੂਪ ਆਏ। ਸਬੈ ਬਾਲ ਕੌ ਲੈ ਭਵਾਨੀ ਬਤਾਏ। ੭੦।","roman":"Kahaa lau bakhaano jite bhoop aae | sabai baal kau lai bhavaanee bataae | 70 |","meaning_en":"How far can I describe all the kings that came? Bhavani (Sarasvati) took the maiden and showed her them all.","page":809,"meaning_status":"draft","note":"ਭਵਾਨੀ: here used for the goddess guiding her (Sarasvati)."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":809,"meaning_status":"draft"},{"type":"verse","number":[71],"number_text":"੭੧।","page":809,"lines":[{"gurmukhi":"ਆਨਿ ਜੁਰੇ ਨ੍ਰਿਪ ਮੰਡਲ ਜੇਤਿ ਤੇਤ ਸਬੈ ਤਿਨ ਤਾਸ ਦਿਖਾਏ।","roman":"Aani jure nrip mandal jeti tet sabai tin taas dikhaae |","meaning_en":"As many kings as had come and gathered, she showed them all to her.","page":809,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖ ਫਿਰੀ ਚਹੂੰ ਚਕ੍ਰਨ ਕੋ ਨ੍ਰਿਪ ਰਾਜ ਕੁਮਾਰਿ ਹ੍ਰਿਦੈ ਨਹੀ ਲਿਆਏ।","roman":"Dekh phiree chahoon chakran ko nrip raaj kumaari hridai nahee liaae |","meaning_en":"She went round looking at the kings of the four quarters, but the princess did not bring any into her heart.","page":809,"meaning_status":"draft"},{"gurmukhi":"ਹਾਰਿ ਪਰਿਓ ਸਭ ਹੀ ਭਟ ਮੰਡਲ ਭੂਪਤਿ ਹੇਰਿ ਦਸਾ ਮੁਰਝਾਏ।","roman":"Haari pario sabh hee bhat mandal bhoopti heri dasaa murjhaae |","meaning_en":"The whole company of warriors was defeated; the kings, seeing their own state, withered.","page":809,"meaning_status":"draft"},{"gurmukhi":"ਫੂਕ ਭਏ ਮੁਖ ਸੂਕ ਗਏ ਸਬ ਰਾਜ ਕੁਮਾਰਿ ਫਿਰੇ ਘਰਿ ਆਏ। ੭੧।","roman":"Phook bhae mukh sook gae sab raaj kumaari phire ghari aae | 71 |","meaning_en":"They became like blown-out things, their faces dried up, and the princes all turned back home.","page":809,"meaning_status":"draft","note":"ਫੂਕ ਭਏ: 'became like empty air'; uncertain."}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":809,"lines":[{"gurmukhi":"ਤਉ ਲਗਿ ਆਨ ਗਏ ਅਜਿਰਾਜ ਸੁ ਰਾਜਨ ਰਾਜ ਬਡੋ ਦਲ ਲੀਨੇ।","roman":"Tau lagi aan gae ajiraaj su raajan raaj bado dal leene |","meaning_en":"Just then came Aj, king of kings, with a great army,","page":809,"meaning_status":"draft"},{"gurmukhi":"ਅੰਬਰ ਅਨੂਪ ਧਰੇ ਪਸਮੰਬਰ ਸੰਬਰ ਕੇ ਅਰਿ ਕੀ ਛਬਿ ਛੀਨੇ।","roman":"Anbar anoop dhare pasmanbar sanbar ke ari kee chhabi chheene |","meaning_en":"wearing incomparable garments and fine woollens, outshining the beauty of the god of love (enemy of Sambar).","page":809,"meaning_status":"draft","note":"ਪਸਮੰਬਰ: 'pashmina garments'; ਸੰਬਰ ਕੇ ਅਰਿ: Kama, enemy of Sambar."},{"gurmukhi":"ਬੇਖਨ ਬੇਖ ਚੜੇ ਸੰਗ ਹ੍ਵੈ ਨ੍ਰਿਪ ਹਾਨ ਸਬੈ ਸੁਖ ਧਾਮ ਨਵੀਨੇ।","roman":"Bekhan bekh chare sang hvai nrip haan sabai sukh dhaam naveene |","meaning_en":"Kings in many guises rode with him, all newly made abodes of happiness;","page":810,"meaning_status":"draft","note":"ਹਾਨ: uncertain; line obscure."},{"gurmukhi":"ਆਨਿ ਗਏ ਜਰਿਕੰਬਰ ਸੇ ਅੰਬਰ ਸੇ ਨ੍ਰਿਪ ਕੰਬਰ ਕੀਨੇ। ੭੨।","roman":"Aani gae jarikanbar se anbar se nrip kanbar keene | 72 |","meaning_en":"he came in garments of gold brocade, and made (other) kings look as if clad in rough blankets.","page":810,"meaning_status":"draft","note":"ਜਰਿਕੰਬਰ: 'gold-thread cloth'; ਕੰਬਰ: 'blanket'; reading of the contrast is uncertain."}]},{"type":"verse","number":[73],"number_text":"੭੩।","page":810,"lines":[{"gurmukhi":"ਪਾਤਿ ਹੀ ਪਾਤਿ ਬਨਾਇ ਬਡੋ ਦਲ ਢੋਲ ਮ੍ਰਿਦੰਗ ਸੁਰੰਗ ਬਜਾਇ।","roman":"Paati hee paati banaai bado dal dhol mridang surang bajaai |","meaning_en":"Forming his great army in rows, sounding drums, mridangs and fine instruments,","page":810,"meaning_status":"draft"},{"gurmukhi":"ਭੂਖਨ ਚਾਰੁ ਦਿਪੈ ਸਬ ਅੰਗ ਬਿਲੋਕਿ ਅਨੰਗ ਪ੍ਰਭਾ ਮੁਰਛਾਏ।","roman":"Bhookhan chaaru dipai sab ang biloki anang prabhaa murchhaae |","meaning_en":"with fine ornaments shining on every limb, so that seeing him the god of love swooned at his splendour,","page":810,"meaning_status":"draft"},{"gurmukhi":"ਬਾਜਤ ਚੰਗ ਮ੍ਰਿਦੰਗ ਉਪੰਗ ਸੁਰੰਗ ਸੁ ਨਾਦ ਸਬੈ ਸੁਨਿ ਪਾਏ।","roman":"Baajat chang mridang upang surang su naad sabai suni paae |","meaning_en":"with chang, mridang, upang and fine instruments playing, whose sounds all could hear;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝ ਰਹੇ ਰਿਝਵਾਰ ਸਬੈ ਲਖਿ ਰੂਪ ਅਨੂਪ ਸਰਾਹਤ ਆਏ। ੭੩।","roman":"Reejh rahe rijhvaar sabai lakhi roop anoop saraahat aae | 73 |","meaning_en":"all the connoisseurs were charmed, seeing his incomparable beauty, and came praising.","page":810,"meaning_status":"draft"}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":810,"lines":[{"gurmukhi":"ਜੈਸ ਸਰੂਪ ਲਖਿਓ ਅਜਿ ਕੋ ਹਮ ਤੈਸ ਸਰੂਪ ਨ ਅਉਰ ਬਿਚਾਰੇ।","roman":"Jais saroop lakhio aji ko ham tais saroop na aur bichaare |","meaning_en":"'Such a form as we have seen in Aj, we have known no other such form.","page":810,"meaning_status":"draft"},{"gurmukhi":"ਚੰਦਿ ਚਪਿਓ ਲਖਿ ਕੈ ਮੁਖ ਕੀ ਛਬਿ ਛੇਦ ਪਰੇ ਉਰ ਮੈ ਰਿਸ ਮਾਰੇ।","roman":"Chandi chapio lakhi kai mukh kee chhabi chhed pare ur mai ris maare |","meaning_en":"The moon was abashed seeing the beauty of his face; holes formed in its breast as it was struck with resentment.","page":810,"meaning_status":"draft","note":"Explains the moon's spots poetically."},{"gurmukhi":"ਤੇਜ ਸਰੂਪ ਬਿਲੋਕਿ ਕੈ ਪਾਵਕ ਚਿਤਿ ਚਿਰੀ ਗ੍ਰਿਹ ਅਉਰਨ ਜਾਰੇ।","roman":"Tej saroop biloki kai paavak chiti chiree grih auran jaare |","meaning_en":"Seeing his form of radiance, fire, sore at heart, burned the houses of others.","page":810,"meaning_status":"draft","note":"ਚਿਰੀ: read as 'vexed/irritated'; uncertain."},{"gurmukhi":"ਜੈਸ ਪ੍ਰਭਾ ਲਖਿਓ ਅਜਿ ਕੋ ਹਮ ਤੈਸ ਸਰੂਪ ਨ ਭੂਪ ਨਿਹਾਰੇ। ੭੪।","roman":"Jais prabhaa lakhio aji ko ham tais saroop na bhoop nihaare | 74 |","meaning_en":"Such splendour as we have seen in Aj, we have seen in no king.'","page":810,"meaning_status":"draft"}]},{"type":"verse","number":[75],"number_text":"੭੫।","page":810,"lines":[{"gurmukhi":"ਸੁੰਦਰ ਜੁਆਨ ਸਰੂਪ ਮਹਾਨ ਪ੍ਰਧਾਨ ਚਹੁੰ ਚਕ ਮੈ ਹਮ ਜਾਨਿਓ।","roman":"Sundar juaan saroop mahaan pradhaan chahun chak mai ham jaanio |","meaning_en":"'Handsome, young, of great form, we know him as foremost in the four quarters.","page":810,"meaning_status":"draft"},{"gurmukhi":"ਭਾਨੁ ਸਮਾਨ ਪ੍ਰਭਾ ਨ ਪ੍ਰਮਾਨ ਕਿ ਰਾਵ ਕਿ ਰਾਨ ਮਹਾਨ ਬਖਾਨਿਓ।","roman":"Bhaanu samaan prabhaa na pramaan ki raav ki raan mahaan bakhaanio |","meaning_en":"His radiance like the sun cannot be measured; is he a raja or a rana? He is called great.","page":810,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵ ਅਦੇਵ ਚਕੇ ਅਪਨੇ ਚਿਤਿ ਚੰਦ ਸਰੂਪ ਨਿਸਾ ਪਹਿਚਾਨਿਓ।","roman":"Dev adev chake apne chiti chand saroop nisaa pahichaanio |","meaning_en":"Gods and demons were amazed in their hearts; the night recognised him as the form of the moon;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਦਿਉਸ ਕੈ ਭਾਨੁ ਮੁਨਿਓ ਭਗਵਾਨ ਪਛਾਨ ਮਨੈ ਘਨ ਮੋਰਨ ਮਾਨਿਓ। ੭੫।","roman":"Dius kai bhaanu munio bhagvaan pachhaan manai ghan moran maanio | 75 |","meaning_en":"the day took him for the sun, the sages recognised him as God, and the peacocks took him in their minds as a cloud.","page":810,"meaning_status":"draft"}]},{"type":"verse","number":[76],"number_text":"੭੬।","page":810,"lines":[{"gurmukhi":"ਬੋਲਿ ਉਠੇ ਪਿਕ ਜਾਨ ਬਸੰਤ ਚਕੋਰਨ ਚੰਦ ਸਰੂਪ ਬਖਾਨਿਓ।","roman":"Boli uthe pik jaan basant chakoran chand saroop bakhaanio |","meaning_en":"The cuckoos sang out, taking him for spring; the chakors called him the form of the moon;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਸਾਂਤਿ ਸੁਭਾਵ ਲਖਿਓ ਸਭ ਸਾਧਨ ਜੋਧਨ ਕ੍ਰੋਧ ਪ੍ਰਤਛ ਪ੍ਰਮਾਨਿਓ।","roman":"Saanti subhaav lakhio sabh saadhan jodhan krodh pratachh pramaanio |","meaning_en":"all the holy men saw in him a peaceful nature; warriors took him plainly as anger itself;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਬਾਲਨ ਬਾਲ ਸੁਭਾਵ ਲਖਿਓ ਤਿਹ ਸਤ੍ਰਨ ਕਾਲ ਸਰੂਪ ਪਛਾਨਿਓ।","roman":"Baalan baal subhaav lakhio tih satran kaal saroop pachhaanio |","meaning_en":"children saw in him a child's nature; enemies recognised him as the form of death;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵਲ ਦੇਵ ਅਦੇਵਨ ਕੈ ਸਿਵ ਰਾਜਨ ਰਾਜਿ ਬਡੋ ਜੀਅ ਜਾਨਿਓ। ੭੬।","roman":"Deval dev adevan kai siv raajan raaji bado jeea jaanio | 76 |","meaning_en":"to gods and demons he was the God of temples; Shiva knew him in his heart as a great king of kings.","page":810,"meaning_status":"draft","note":"ਦੇਵਲ ਦੇਵ ... ਸਿਵ: line uncertain."}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":810,"lines":[{"gurmukhi":"ਸਾਧਨ ਸਿਧ ਸਰੂਪ ਲਖਿਓ ਤਿਹ ਸਤ੍ਰਨ ਸਤ੍ਰ ਸਮਾਨ ਬਸੇਖਿਓ।","roman":"Saadhan sidh saroop lakhio tih satran satr samaan basekhio |","meaning_en":"Seekers saw him as the form of attainment; enemies saw him especially as an enemy;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਚੋਰਨ ਭੋਰ ਕਰੋਰਨ ਮੋਰਨ ਤਾਸੁ ਸਹੀ ਘਨ ਕੈ ਅਵਿਰੇਖਿਓ।","roman":"Choran bhor karoran moran taasu sahee ghan kai avirekhio |","meaning_en":"thieves saw him as the dawn, and millions of peacocks saw him truly as a cloud;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਕਾਮ ਸਰੂਪ ਸਭੈ ਪੁਰ ਨਾਰਨ ਸੰਭੂ ਸਮਾਨ ਸਬੂ ਗਨ ਦੇਖਿਓ।","roman":"Kaam saroop sabhai pur naaran sanbhoo samaan saboo gan dekhio |","meaning_en":"all the women of the city saw him as the form of the god of love; all Shiva's attendants saw him as like Shiva;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਸੀਪ ਸ੍ਵਾਂਤਿ ਕੀ ਬੂੰਦ ਤਿਸੈ ਕਰਿ ਰਾਜਨ ਰਾਜ ਬਡੋ ਤਿਹ ਪੇਖਿਓ। ੭੭।","roman":"Seep svaanti kee boond tisai kari raajan raaj bado tih pekhio | 77 |","meaning_en":"the oyster saw him as the drop of Swati; and kings saw him as a great king of kings.'","page":810,"meaning_status":"draft"}]},{"type":"verse","number":[78],"number_text":"੭੮।","page":810,"lines":[{"gurmukhi":"ਕੰਬਰ ਜਿਉ ਜਰਿਕੰਬਰ ਕੀ ਢਿਗ ਤਿਉ ਅਵਿਨੰਬਰ ਤੀਰ ਸੁਹਾਏ।","roman":"Kanbar jiu jarikanbar kee dhig tiu avinanbar teer suhaae |","meaning_en":"As a blanket beside gold brocade, so (other kings) looked beside the lord of the earth.","page":810,"meaning_status":"draft","note":"ਅਵਿਨੰਬਰ: read as 'lord of the earth'; line uncertain."},{"gurmukhi":"ਨਾਕ ਲਖੇ ਰਿਸ ਮਾਨ ਸੂਆ ਮਨ ਨੈਨ ਦੋਊ ਲਖਿ ਏਣ ਲਜਾਏ।","roman":"Naak lakhe ris maan sooaa man nain do'oo lakhi en lajaae |","meaning_en":"Seeing his nose, the parrot was angered in mind; seeing his two eyes, the deer was ashamed;","page":810,"meaning_status":"draft"},{"gurmukhi":"ਪੇਖਿ ਗੁਲਾਬ ਸਰਾਬ ਪੀਐ ਜਨੁ ਪੇਖਤ ਅੰਗ ਅਨੰਗ ਰਿਸਾਏ।","roman":"Pekhi gulaab saraab peeai janu pekhat ang anang risaae |","meaning_en":"seeing him, the rose (blushed) as if it had drunk wine; seeing his limbs, the god of love was angered;","page":811,"meaning_status":"draft"},{"gurmukhi":"ਕੰਠ ਕਪੋਤ ਕਟੂ ਪਰ ਕੇਹਰ ਰੋਸ ਰਸੇ ਗ੍ਰਿਹ ਭੂਲਿ ਨ ਆਏ। ੭੮।","roman":"Kanth kapot katoo par kehar ros rase grih bhooli na aae | 78 |","meaning_en":"the pigeon (for his neck) and the lion (for his waist) were so filled with resentment that they never came home again.","page":811,"meaning_status":"draft","note":"ਕੰਠ ਕਪੋਤ ਕਟੂ ਪਰ ਕੇਹਰ: neck vs pigeon, waist vs lion; uncertain."}]},{"type":"verse","number":[79],"number_text":"੭੯।","page":811,"lines":[{"gurmukhi":"ਪੇਖਿ ਸਰੂਪ ਸਿਰਾਤ ਨ ਲੋਚਨ ਘੂਟਤ ਹੈ ਜਨੁ ਘੂਟ ਅਮੀ ਕੇ।","roman":"Pekhi saroop siraat na lochan ghootat hai janu ghoot amee ke |","meaning_en":"Seeing his form, the eyes are never satisfied, as if they were drinking draughts of nectar.","page":811,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਬਜਾਵਤ ਤਾਲ ਬਤਾਵਤ ਹੈ ਜਨੋ ਆਛਰ ਹੀ ਕੇ।","roman":"Gaavat geet bajaavat taal bataavat hai jano aachhar hee ke |","meaning_en":"Singing songs and beating time, they seem to be the apsaras themselves.","page":811,"meaning_status":"draft"},{"gurmukhi":"ਭਾਵਤ ਨਾਰਿ ਸੁਹਾਵਤ ਗਾਰ ਦਿਵਾਵਤ ਹੈ ਭਰਿ ਆਨੰਦ ਜੀ ਕੇ।","roman":"Bhaavat naari suhaavat gaar divaavat hai bhari aanand jee ke |","meaning_en":"The women, pleased, sing the lovely wedding teasing-songs, full of joy of heart:","page":811,"meaning_status":"draft","note":"ਗਾਰ: 'gaali', the playful abuse-songs sung at weddings."},{"gurmukhi":"ਤੂ ਸੁ ਕੁਮਾਰ ਰਚੀ ਕਰਤਾਰ ਕਹੈ ਅਬਿਚਾਰ ਤ੍ਰੀਆ ਬਰ ਨੀਕੇ। ੭੯।","roman":"Too su kumaar rachee kartaar kahai abichaar treeaa bar neeke | 79 |","meaning_en":"'You, prince, the Creator made for her,' they say without hesitation; 'a fine groom for the bride.'","page":811,"meaning_status":"draft"}]},{"type":"verse","number":[80],"number_text":"੮੦।","page":811,"lines":[{"gurmukhi":"ਦੇਖਤ ਰੂਪ ਸਿਰਾਤ ਨ ਲੋਚਨ ਪੇਖਿ ਛਕੀ ਪੀਅ ਕੀ ਛਬਿ ਨਾਰੀ।","roman":"Dekhat roop siraat na lochan pekhi chhakee peea kee chhabi naaree |","meaning_en":"Looking at his form, her eyes are never satisfied; the woman is overcome by the beauty of her beloved.","page":811,"meaning_status":"draft"},{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਬਜਾਵਤ ਢੋਲ ਮ੍ਰਿਦੰਗ ਮੁਚੰਗਨ ਕੀ ਧੁਨਿ ਭਾਰੀ।","roman":"Gaavat geet bajaavat dhol mridang muchangan kee dhuni bhaaree |","meaning_en":"They sing songs and beat drums, with the loud sound of mridang and jew's-harp.","page":811,"meaning_status":"draft"},{"gurmukhi":"ਆਵਤ ਜਾਤ ਜਿਤੀ ਪੁਰ ਨਾਗਰ ਗਾਗਰਿ ਡਾਰਿ ਲਖੈ ਦੁਤਿ ਭਾਰੀ।","roman":"Aavat jaat jitee pur naagar gaagri daari lakhai duti bhaaree |","meaning_en":"All the city women coming and going put down their water-pots to see his great radiance:","page":811,"meaning_status":"draft"},{"gurmukhi":"ਰਾਜ ਕਰੋ ਤਬ ਲੌ ਜਬ ਲੌ ਮਹਿ ਜਉ ਲਗ ਗੰਗ ਬਹੈ ਜਮੁਨਾ ਰੀ। ੮੦।","roman":"Raaj karo tab lau jab lau mahi jau lag gang bahai jamunaa ree | 80 |","meaning_en":"'May you rule on the earth as long as the Ganga and the Yamuna flow.'","page":811,"meaning_status":"draft"}]},{"type":"verse","number":[81],"number_text":"੮੧।","page":811,"lines":[{"gurmukhi":"ਜਉਨ ਪ੍ਰਭਾ ਅਜਿ ਰਾਜ ਕੀ ਰਾਜਤ ਸੋ ਕਹਿ ਕੈ ਕਿਹ ਭਾਤਿ ਗਨਾਊ।","roman":"Jaun prabhaa aji raaj kee raajat so kahi kai kih bhaati ganaaoo |","meaning_en":"The splendour that shines in King Aj, how can I tell and count it?","page":811,"meaning_status":"draft"},{"gurmukhi":"ਜਉਨ ਪ੍ਰਭਾ ਕਬਿ ਦੇਤ ਸਬੈ ਜੌ ਪੈ ਤਾਸ ਕਹੋ ਜੀਅ ਬੀਚ ਲਜਾਊ।","roman":"Jaun prabhaa kabi det sabai jau pai taas kaho jeea beech lajaaoo |","meaning_en":"Whatever likenesses all poets give, if I say them of him, I feel ashamed at heart.","page":811,"meaning_status":"draft"},{"gurmukhi":"ਹਉ ਚਹੂੰ ਓਰ ਫਿਰਿਓ ਬਸੁਧਾ ਛਬਿ ਅੰਗਨ ਕੀਨ ਕਹੂੰ ਕੋਈ ਪਾਊ।","roman":"Hau chahoon or phirio basudhaa chhabi angan keen kahoon koee paaoo |","meaning_en":"I have wandered the earth in all four directions; where could I find anyone with such beauty of limbs?","page":811,"meaning_status":"draft"},{"gurmukhi":"ਲੇਖਨ ਊਖ ਹ੍ਵੈ ਜਾਤ ਲਿਖੋ ਛਬਿ ਆਨਨ ਤੇ ਕਿਮਿ ਭਾਖਿ ਸੁਨਾਊ। ੮੧।","roman":"Lekhan ookh hvai jaat likho chhabi aanan te kimi bhaakhi sunaaoo | 81 |","meaning_en":"The pen, though it were sugar-cane, cannot write his beauty; how can I tell it with my mouth?","page":811,"meaning_status":"draft","note":"ਲੇਖਨ ਊਖ ਹ੍ਵੈ ਜਾਤ: read as 'pens made of reed (cane) wear out'; uncertain."}]},{"type":"verse","number":[82],"number_text":"੮੨।","page":811,"lines":[{"gurmukhi":"ਨੈਨਨ ਬਾਨ ਚਹੂੰ ਦਿਸ ਮਾਰਤ ਘਾਇਲ ਕੈ ਪੁਰ ਬਾਸਨ ਡਾਰੀ।","roman":"Nainan baan chahoon dis maarat ghaail kai pur baasan daaree |","meaning_en":"With the arrows of his eyes he strikes in all directions, laying the city-dwellers low, wounded.","page":811,"meaning_status":"draft"},{"gurmukhi":"ਸਾਰਸ੍ਵਤੀ ਨ ਸਕੈ ਕਹਿ ਰੂਪ ਸਿੰਗਾਰ ਕਹੈ ਮਤਿ ਕਉਨ ਬਿਚਾਰੀ।","roman":"Saarsvatee na sakai kahi roop singaar kahai mati kaun bichaaree |","meaning_en":"Even Sarasvati cannot tell the adornment of his beauty; what poor intellect could tell it?","page":811,"meaning_status":"draft"},{"gurmukhi":"ਕੋਕਿਲ ਕੰਠਿ ਹਰਿਓ ਨ੍ਰਿਪ ਨਾਇਕ ਛੀਨ ਕਪੋਤ ਕੀ ਗ੍ਰੀਵ ਅਨਿਆਰੀ।","roman":"Kokil kanthi hario nrip naaik chheen kapot kee greev aniaaree |","meaning_en":"The lord of kings has taken away the cuckoo's voice and seized the fine neck of the pigeon.","page":811,"meaning_status":"draft"},{"gurmukhi":"ਰੀਝ ਗਿਰੇ ਨਰ ਨਾਰਿ ਧਰਾ ਪਰ ਘੂਮਤਿ ਹੈ ਜਨੁ ਘਾਇਲ ਭਾਰੀ। ੮੨।","roman":"Reejh gire nar naari dharaa par ghoomti hai janu ghaail bhaaree | 82 |","meaning_en":"Men and women, charmed, fall to the ground and reel as if badly wounded.","page":811,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":811,"meaning_status":"draft"},{"type":"verse","number":[83],"number_text":"੮੩।","page":811,"lines":[{"gurmukhi":"ਨਿਰਖਿ ਰੂਪ ਅਜਿ ਰਾਜ ਕੋ ਰੀਝ ਰਹੇ ਨਰ ਨਾਰਿ।","roman":"Nirkhi roop aji raaj ko reejh rahe nar naari |","meaning_en":"Seeing the beauty of King Aj, men and women were charmed,","page":811,"meaning_status":"draft"},{"gurmukhi":"ਇੰਦ੍ਰ ਕਿ ਚੰਦ੍ਰ ਕਿ ਸੂਰ ਇਹਿ ਇਹ ਬਿਧਿ ਕਰਤ ਬਿਚਾਰ। ੮੩।","roman":"Indr ki chandr ki soor ihi ih bidhi karat bichaar | 83 |","meaning_en":"and they wondered thus: 'Is he Indra, or the moon, or the sun?'","page":811,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"Kabitt.","page":812,"meaning_status":"draft"},{"type":"verse","number":[84],"number_text":"੮੪।","page":812,"lines":[{"gurmukhi":"ਨਾਗਨ ਕੇ ਛਉਨਾ ਹੈਂ ਕਿ ਕੀਨੇ ਕਾਹੂੰ ਟਉਨਾ ਹੈਂ","roman":"Naagan ke chhaunaa hain ki keene kaahoon taunaa hain","meaning_en":"Are they young serpents, or has someone cast a spell,","page":812,"meaning_status":"draft","note":"Describing Aj's eyes; ਟਉਨਾ: 'spell/charm'."},{"gurmukhi":"ਕਿ ਕਾਮ ਕੇ ਖਿਲਉਨਾ ਹੈਂ ਬਨਾਏ ਹੈਂ ਸੁਧਾਰ ਕੇ।","roman":"Ki kaam ke khilaunaa hain banaae hain sudhaar ke |","meaning_en":"or are they toys of the god of love, made with care?","page":812,"meaning_status":"draft"},{"gurmukhi":"ਇਸਤ੍ਰਿਨ ਕੇ ਪ੍ਰਾਨ ਹੈਂ ਕਿ ਸੁੰਦਰਤਾ ਕੀ ਖਾਨ ਹੈਂ","roman":"Istrin ke praan hain ki sundartaa kee khaan hain","meaning_en":"Are they the life-breath of women, or the mine of beauty,","page":812,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਕਾਮ ਕੇ ਕਲਾਨ ਬਿਧਿ ਕੀਨੇ ਹੈਂ ਬਿਚਾਰ ਕੇ।","roman":"Ki kaam ke kalaan bidhi keene hain bichaar ke |","meaning_en":"or has the Maker fashioned them with thought from the arts of love?","page":812,"meaning_status":"draft"},{"gurmukhi":"ਚਾਤੁਰਤਾ ਕੇ ਭੇਸ ਹੈਂ ਕਿ ਰੂਪ ਕੇ ਨਰੇਸ ਹੈਂ","roman":"Chaaturtaa ke bhes hain ki roop ke nares hain","meaning_en":"Are they the guise of cleverness, or the kings of beauty,","page":812,"meaning_status":"draft"},{"gurmukhi":"ਕਿ ਸੁੰਦਰ ਸੁ ਦੇਸ ਏਸ ਕੀਨੇ ਚੰਦ੍ਰ ਸਾਰ ਕੇ।","roman":"Ki sundar su des es keene chandr saar ke |","meaning_en":"or lords of a beautiful land, made from the essence of the moon?","page":812,"meaning_status":"draft"},{"gurmukhi":"ਤੇਗ ਹੈਂ ਕਿ ਤੀਰ ਹੈਂ ਕਿ ਬਾਨਾ ਬਾਂਧੇ ਬੀਰ ਹੈਂ","roman":"Teg hain ki teer hain ki baanaa baandhe beer hain","meaning_en":"Are they swords, or arrows, or warriors in armour?","page":812,"meaning_status":"draft"},{"gurmukhi":"ਸੁ ਐਸੇ ਨੇਤ੍ਰ ਅਜਿ ਕੇ ਬਿਲੋਕੀਐ ਸੰਭਾਰ ਕੇ। ੮੪।","roman":"Su aise netr aji ke bilokeeai sanbhaar ke | 84 |","meaning_en":"Such are the eyes of Aj; look at them with care.","page":812,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":812,"meaning_status":"draft"},{"type":"verse","number":[85],"number_text":"੮੫।","page":812,"lines":[{"gurmukhi":"ਤੀਰਨ ਤੇ ਤਰਵਾਰਨ ਸੇ ਮ੍ਰਿਗ ਬਾਰਨ ਸੇ ਅਵਿਲੋਕਹੁ ਜਾਈ।","roman":"Teeran te tarvaaran se mrig baaran se avilokhu jaaee |","meaning_en":"Go and see (his eyes), like arrows, like swords, like the eyes of a young deer.","page":812,"meaning_status":"draft","note":"ਮ੍ਰਿਗ ਬਾਰਨ: 'young deer' or 'deer (and) elephants'; uncertain."},{"gurmukhi":"ਰੀਝ ਰਹੀ ਰਿਝਵਾਰ ਲਖੇ ਦੁਤਿ ਭਾਖਿ ਪ੍ਰਭਾ ਨਹੀ ਜਾਤ ਬਤਾਈ।","roman":"Reejh rahee rijhvaar lakhe duti bhaakhi prabhaa nahee jaat bataaee |","meaning_en":"The connoisseurs were charmed seeing his radiance; his splendour cannot be told in words.","page":812,"meaning_status":"draft"},{"gurmukhi":"ਸੰਗਿ ਚਲੀ ਉਠਿ ਬਾਲ ਬਿਲੋਕਨ ਮੋਰ ਚਕੋਰ ਰਹੇ ਉਰਝਾਈ।","roman":"Sangi chalee uthi baal bilokan mor chakor rahe urjhaaee |","meaning_en":"The maidens rose and went along to look, as peacocks and chakors are entangled (by cloud and moon).","page":812,"meaning_status":"draft"},{"gurmukhi":"ਡੀਠਿ ਪਰੈ ਅਜਿ ਰਾਜ ਜਬੈ ਚਿਤ ਦੇਖਤ ਹੀ ਤ੍ਰੀਅ ਲੀਨ ਚੁਰਾਈ। ੮੫।","roman":"Deethi parai aji raaj jabai chit dekhat hee treea leen churaaee | 85 |","meaning_en":"When King Aj came into sight, the moment she saw him, the woman's heart was stolen.","page":812,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤੋਮਰ ਛੰਦ","roman":"Tomar chhand","meaning_en":"Tomar metre.","page":812,"meaning_status":"draft"},{"type":"verse","number":[86],"number_text":"੮੬।","page":812,"lines":[{"gurmukhi":"ਅਵਿਲੋਕੀਆ ਅਜਿ ਰਾਜ। ਅਤਿ ਰੂਪ ਸਰਬ ਸਮਾਜ।","roman":"Avilokeeaa aji raaj | ati roop sarab samaaj |","meaning_en":"She looked at King Aj, the most beautiful of the whole assembly;","page":812,"meaning_status":"draft"},{"gurmukhi":"ਅਤਿ ਰੀਝ ਕੈ ਹਸ ਬਾਲ। ਗੁਹਿ ਫੂਲ ਮਾਲ ਉਤਾਲ। ੮੬।","roman":"Ati reejh kai has baal | guhi phool maal utaal | 86 |","meaning_en":"greatly charmed, the maiden smiled and quickly strung a garland of flowers.","page":812,"meaning_status":"draft"}]},{"type":"verse","number":[87],"number_text":"੮੭।","page":812,"lines":[{"gurmukhi":"ਗਹਿ ਫੂਲ ਕੀ ਕਰਿ ਮਾਲ। ਅਤਿ ਰੂਪਵੰਤ ਸੁ ਬਾਲ।","roman":"Gahi phool kee kari maal | ati roopvant su baal |","meaning_en":"Taking the flower garland in her hand, the very beautiful maiden","page":812,"meaning_status":"draft"},{"gurmukhi":"ਤਿਸੁ ਡਾਰੀਆ ਉਰਿ ਆਨਿ। ਦਸ ਚਾਰਿ ਚਾਰਿ ਨਿਧਾਨਿ। ੮੭।","roman":"Tisu daareeaa uri aani | das chaari chaari nidhaani | 87 |","meaning_en":"came and placed it on the breast of him, treasury of the eighteen (sciences).","page":812,"meaning_status":"draft"}]},{"type":"verse","number":[88],"number_text":"੮੮।","page":812,"lines":[{"gurmukhi":"ਤਿਹ ਦੇਬਿ ਆਗਿਆ ਕੀਨ। ਦਸ ਚਾਰਿ ਚਾਰਿ ਪ੍ਰਬੀਨ।","roman":"Tih debi aagiaa keen | das chaari chaari prabeen |","meaning_en":"The goddess gave a command to him, skilled in the eighteen (sciences),","page":812,"meaning_status":"draft","note":"Line order suggests the goddess's words follow to the princess; uncertain who is addressed."},{"gurmukhi":"ਸੁਨਿ ਸੁੰਦਰੀ ਇਮ ਬੈਨ। ਸਸਿ ਕ੍ਰਾਂਤ ਸੁੰਦਰ ਨੈਨ। ੮੮।","roman":"Suni sundree im bain | sasi kraant sundar nain | 88 |","meaning_en":"'Listen, beautiful one, to these words, you whose lovely eyes outshine the moon:","page":812,"meaning_status":"draft"}]},{"type":"verse","number":[89],"number_text":"੮੯।","page":812,"lines":[{"gurmukhi":"ਤਵ ਜੋਗ ਹੈ ਅਜਿ ਰਾਜ। ਸੁਨ ਰੂਪਵੰਤ ਸਲਾਜ।","roman":"Tav jog hai aji raaj | sun roopvant salaaj |","meaning_en":"King Aj is fit for you; listen, beautiful and modest one;","page":812,"meaning_status":"draft"},{"gurmukhi":"ਬਰੁ ਆਜੁ ਤਾ ਕਹ ਜਾਇ। ਸੁਨਿ ਬੈਨਿ ਸੁੰਦਰ ਕਾਇ। ੮੯।","roman":"Baru aaju taa kah jaai | suni baini sundar kaai | 89 |","meaning_en":"go and wed him today; hear my words, lovely one.'","page":812,"meaning_status":"draft"}]},{"type":"verse","number":[90],"number_text":"੯੦।","page":812,"lines":[{"gurmukhi":"ਗਹਿ ਫੂਲ ਮਾਲ ਪ੍ਰਬੀਨ। ਉਰਿ ਡਾਰ ਤਾ ਕੇ ਦੀਨ।","roman":"Gahi phool maal prabeen | uri daar taa ke deen |","meaning_en":"The skilful one took the flower garland and put it on his breast.","page":812,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਬਾਜ ਤੂਰ ਅਨੇਕ। ਡਫ ਬੀਣ ਬੇਣ ਬਸੇਖ। ੯੦।","roman":"Tab baaj toor anek | daph been ben basekh | 90 |","meaning_en":"Then many trumpets sounded, and tambourines, vinas and flutes especially.","page":812,"meaning_status":"draft"}]},{"type":"verse","number":[91],"number_text":"੯੧।","page":813,"lines":[{"gurmukhi":"ਡਫ ਬਾਜ ਢੋਲ ਮ੍ਰਿਦੰਗ। ਅਤਿ ਤੂਰ ਤਾਨ ਤਰੰਗ।","roman":"Daph baaj dhol mridang | ati toor taan tarang |","meaning_en":"Tambourines, dhols and mridangs played, and many waves of trumpet tunes;","page":813,"meaning_status":"draft"},{"gurmukhi":"ਨਯ ਬਾਸੁਰੀ ਅਰੁ ਬੈਨ। ਬਹੁ ਸੁੰਦਰੀ ਸੁਭ ਨੈਨ। ੯੧।","roman":"Nay baasuree aru bain | bahu sundree subh nain | 91 |","meaning_en":"nai, flutes and pipes, and many beautiful women with lovely eyes.","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[92],"number_text":"੯੨।","page":813,"lines":[{"gurmukhi":"ਤਿਹ ਬਿਆਹਿ ਕੈ ਅਜਿ ਰਾਜਿ। ਬਹੁ ਭਾਤਿ ਲੈ ਕਰ ਦਾਜ।","roman":"Tih biaahi kai aji raaji | bahu bhaati lai kar daaj |","meaning_en":"King Aj married her, and taking a dowry of many kinds,","page":813,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਰਿਹ ਆਈਆ ਸੁਖ ਪਾਇ। ਡਫ ਬੇਣ ਬੀਣ ਬਜਾਇ। ੯੨।","roman":"Grih aaeeaa sukh paai | daph ben been bajaai | 92 |","meaning_en":"came home in happiness, with tambourines, flutes and vinas playing.","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[93],"number_text":"੯੩।","page":813,"lines":[{"gurmukhi":"ਅਜਿ ਰਾਜ ਰਾਜ ਮਹਾਨ। ਦਸ ਚਾਰਿ ਚਾਰਿ ਨਿਧਾਨ।","roman":"Aji raaj raaj mahaan | das chaari chaari nidhaan |","meaning_en":"King Aj was a great king of kings, treasury of the eighteen (sciences),","page":813,"meaning_status":"draft"},{"gurmukhi":"ਸੁਖ ਸਿੰਧੁ ਸੀਲ ਸਮੁੰਦ੍ਰ। ਜਿਨਿ ਜੀਤਿਆ ਰਣ ਰੁਦ੍ਰ। ੯੩।","roman":"Sukh sindhu seel samundr | jini jeetiaa ran rudr | 93 |","meaning_en":"an ocean of happiness, a sea of good conduct, who conquered Rudra in battle.","page":813,"meaning_status":"draft","note":"ਰਣ ਰੁਦ੍ਰ: may mean 'fierce (Rudra-like) foes in battle'; uncertain."}]},{"type":"verse","number":[94],"number_text":"੯੪।","page":813,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਰਾਜ ਕਮਾਇ। ਸਿਰਿ ਅਤ੍ਰ ਪਤ੍ਰ ਫਿਰਾਇ।","roman":"Ih bhaati raaj kamaai | siri atr patr phiraai |","meaning_en":"In this way he ruled, with the royal canopy waved over his head,","page":813,"meaning_status":"draft"},{"gurmukhi":"ਰਣ ਧੀਰ ਰਾਜ ਬਿਸੇਖ। ਜਗ ਕੀਨ ਜਾਸੁ ਭਿਖੇਖ। ੯੪।","roman":"Ran dheer raaj bisekh | jag keen jaasu bhikhekh | 94 |","meaning_en":"a king especially steadfast in battle, to whom the world became a beggar.","page":813,"meaning_status":"draft","note":"ਭਿਖੇਖ: read as 'beggar'; uncertain."}]},{"type":"verse","number":[95],"number_text":"੯੫।","page":813,"lines":[{"gurmukhi":"ਜਗਜੀਤ ਚਾਰਿ ਦਿਸਾਨ। ਅਜਿ ਰਾਜ ਰਾਜ ਮਹਾਨ।","roman":"Jagjeet chaari disaan | aji raaj raaj mahaan |","meaning_en":"Conqueror of the world in the four directions was King Aj, great king of kings;","page":813,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਦਾਨ ਸੀਲ ਪਹਾਰ। ਦਸ ਚਾਰਿ ਚਾਰਿ ਉਦਾਰ। ੯੫।","roman":"Nrip daan seel pahaar | das chaari chaari udaar | 95 |","meaning_en":"a king who was a mountain of charity and good conduct, generous and master of the eighteen (sciences).","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[96],"number_text":"੯੬।","page":813,"lines":[{"gurmukhi":"ਦੁਤਿਵੰਤਿ ਸੁੰਦਰ ਨੈਨ। ਜਿਹ ਪੇਖਿ ਖਿਝਤ ਮੈਨ।","roman":"Dutivanti sundar nain | jih pekhi khijhat main |","meaning_en":"Radiant, with beautiful eyes, seeing whom the god of love was vexed;","page":813,"meaning_status":"draft"},{"gurmukhi":"ਮੁਖ ਦੇਖਿ ਚੰਦ੍ਰ ਸਰੂਪ। ਚਿਤ ਸੋ ਚੁਰਾਵਤ ਭੂਪ। ੯੬।","roman":"Mukh dekhi chandr saroop | chit so churaavat bhoop | 96 |","meaning_en":"seeing his moon-like face, the king stole people's hearts.","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[97],"number_text":"੯੭।","page":813,"lines":[{"gurmukhi":"ਇਹ ਭਾਤਿ ਕੈ ਬਡ ਰਾਜ। ਬਹੁ ਜਗ ਧਰਮ ਸਮਾਜ।","roman":"Ih bhaati kai bad raaj | bahu jag dharam samaaj |","meaning_en":"In this way he ruled greatly, with many sacrifices and works of dharma.","page":813,"meaning_status":"draft"},{"gurmukhi":"ਜਉ ਕਹੋ ਸਰਬ ਬਿਚਾਰ। ਇਕ ਹੋਤ ਕਥਾ ਪਸਾਰ। ੯੭।","roman":"Jau kaho sarab bichaar | ik hot kathaa pasaar | 97 |","meaning_en":"If I tell all the details, the story becomes long;","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[98],"number_text":"੯੮।","page":813,"lines":[{"gurmukhi":"ਤਿਹ ਤੇ ਸੁ ਥੋਰੀਐ ਬਾਤ। ਸੁਨਿ ਲੇਹੁ ਭਾਖੋ ਭ੍ਰਾਤ।","roman":"Tih te su thoreeai baat | suni lehu bhaakho bhraat |","meaning_en":"so I tell it in few words; listen, brother.","page":813,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁ ਜਗ ਧਰਮ ਸਮਾਜ। ਇਹ ਭਾਤਿ ਕੈ ਅਜਿ ਰਾਜ। ੯੮।","roman":"Bahu jag dharam samaaj | ih bhaati kai aji raaj | 98 |","meaning_en":"Many sacrifices and works of dharma King Aj performed in this way.","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[99],"number_text":"੯੯।","page":813,"lines":[{"gurmukhi":"ਜਗ ਆਪਨੋ ਅਜਿ ਮਾਨ। ਤਰਿ ਆਖ ਆਨ ਨ ਆਨ।","roman":"Jag aapno aji maan | tari aakh aan na aan |","meaning_en":"Aj thought the world his own and brought no other under his eye;","page":813,"meaning_status":"draft","note":"ਤਰਿ ਆਖ ਆਨ ਨ ਆਨ: read as 'regarded no one else'; uncertain."},{"gurmukhi":"ਤਬ ਕਾਲ ਕੋਪ ਕ੍ਰਵਾਲ। ਅਜਿ ਜਾਰੀਆ ਮਧਿ ਜ੍ਵਾਲ। ੯੯।","roman":"Tab kaal kop kravaal | aji jaareeaa madhi jvaal | 99 |","meaning_en":"then Kal, in anger, (drew) His sword and burned Aj in His flame.","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[100],"number_text":"੧੦੦।","page":813,"lines":[{"gurmukhi":"ਅਜਿ ਜੋਤਿ ਜੋਤਿ ਮਿਲਾਨ। ਤਬ ਸਰਬ ਦੇਖਿ ਡਰਾਨ।","roman":"Aji joti joti milaan | tab sarab dekhi daraan |","meaning_en":"Aj's light merged into the Light; then all, seeing it, were afraid,","page":813,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮ ਨਾਵ ਖੇਵਟ ਹੀਨ। ਜਿਮ ਦੇਹ ਅਰਬਲ ਛੀਨ। ੧੦੦।","roman":"Jim naav khevat heen | jim deh arbal chheen | 100 |","meaning_en":"like a boat without a boatman, like a body whose life-span is spent,","page":813,"meaning_status":"draft","note":"ਅਰਬਲ: 'life-span'."}]},{"type":"verse","number":[101],"number_text":"੧੦੧।","page":813,"lines":[{"gurmukhi":"ਜਿਮ ਗਾਂਵ ਰਾਵ ਬਿਹੀਨ। ਜਿਮ ਉਰਬਰਾ ਕ੍ਰਿਸ ਛੀਨ।","roman":"Jim gaanv raav biheen | jim urabraa kris chheen |","meaning_en":"like a village without a chief, like fertile land without a farmer,","page":813,"meaning_status":"draft","note":"ਕ੍ਰਿਸ ਛੀਨ: read as 'without cultivation'; uncertain."},{"gurmukhi":"ਜਿਮ ਦਿਰਬ ਹੀਣ ਭੰਡਾਰ। ਜਿਮ ਸਾਹਿ ਹੀਣ ਬਿਪਾਰ। ੧੦੧।","roman":"Jim dirab heen bhandaar | jim saahi heen bipaar | 101 |","meaning_en":"like a treasury without wealth, like trade without a merchant,","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[102],"number_text":"੧੦੨।","page":813,"lines":[{"gurmukhi":"ਜਿਮ ਅਰਥ ਹੀਣ ਕਬਿਤ। ਬਿਨੁ ਪ੍ਰੇਮ ਕੇ ਜਿਮ ਮਿਤ।","roman":"Jim arath heen kabit | binu prem ke jim mit |","meaning_en":"like a poem without meaning, like a friend without love,","page":813,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮ ਰਾਜ ਹੀਣ ਸੁ ਦੇਸ। ਜਿਮ ਸੈਣ ਹੀਨ ਨਰੇਸ। ੧੦੨।","roman":"Jim raaj heen su des | jim sain heen nares | 102 |","meaning_en":"like a land without a king, like a king without an army,","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[103],"number_text":"੧੦੩।","page":813,"lines":[{"gurmukhi":"ਜਿਮ ਗਿਆਨ ਹੀਣ ਜੁਗੇਂਦ੍ਰ। ਜਿਮ ਭੂਮ ਹੀਣ ਮਹੇਂਦ੍ਰ।","roman":"Jim giaan heen jugendr | jim bhoom heen mahendr |","meaning_en":"like a chief of yogis without knowledge, like a great king without land,","page":813,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮ ਅਰਥ ਹੀਣ ਬਿਚਾਰ। ਜਿਮ ਦਰਬ ਹੀਣ ਉਦਾਰ। ੧੦੩।","roman":"Jim arath heen bichaar | jim darab heen udaar | 103 |","meaning_en":"like thought without meaning, like a generous man without wealth,","page":813,"meaning_status":"draft"}]},{"type":"verse","number":[104],"number_text":"੧੦੪।","page":814,"lines":[{"gurmukhi":"ਜਿਮ ਅੰਕੁਸ ਹੀਣ ਗਜੇਸ। ਜਿਮ ਸੈਣ ਹੀਣ ਨਰੇਸ।","roman":"Jim ankus heen gajes | jim sain heen nares |","meaning_en":"like a lordly elephant without a goad, like a king without an army,","page":814,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮ ਸਸਤ੍ਰ ਹੀਣ ਲੁਝਾਰ। ਜਿਮ ਬੁਧਿ ਬਾਝ ਬਿਚਾਰ। ੧੦੪।","roman":"Jim sasatr heen lujhaar | jim budhi baajh bichaar | 104 |","meaning_en":"like a warrior without weapons, like thought without intellect,","page":814,"meaning_status":"draft","note":"ਲੁਝਾਰ: printed so; read as ਜੁਝਾਰ, warrior."}]},{"type":"verse","number":[105],"number_text":"੧੦੫।","page":814,"lines":[{"gurmukhi":"ਜਿਮ ਨਾਰਿ ਹੀਣ ਭਤਾਰ। ਜਿਮ ਕੰਤ ਹੀਣ ਸੁ ਨਾਰ।","roman":"Jim naari heen bhataar | jim kant heen su naar |","meaning_en":"like a husband without a wife, like a wife without a husband,","page":814,"meaning_status":"draft"},{"gurmukhi":"ਜਿਮ ਬੁਧਿ ਹੀਣ ਕਬਿਤ। ਜਿਮ ਪ੍ਰੇਮ ਹੀਣ ਸੁ ਮਿਤ। ੧੦੫।","roman":"Jim budhi heen kabit | jim prem heen su mit | 105 |","meaning_en":"like a poem without intellect, like a friend without love,","page":814,"meaning_status":"draft"}]},{"type":"verse","number":[106],"number_text":"੧੦੬।","page":814,"lines":[{"gurmukhi":"ਜਿਮ ਦੇਸ ਭੂਪ ਬਿਹੀਨ। ਬਿਨੁ ਕੰਤ ਨਾਰਿ ਅਧੀਨ।","roman":"Jim des bhoop biheen | binu kant naari adheen |","meaning_en":"like a land without a king, like a dependent woman without a husband,","page":814,"meaning_status":"draft"},{"gurmukhi":"ਜਿਹ ਭਾਤਿ ਬਿਪ੍ਰ ਅਬਿਦਿ। ਜਿਮ ਅਰਥ ਹੀਣ ਸਬਿਦਿ। ੧੦੬।","roman":"Jih bhaati bipr abidi | jim arath heen sabidi | 106 |","meaning_en":"like a Brahmin without learning, like a word without meaning.","page":814,"meaning_status":"draft"}]},{"type":"verse","number":[107],"number_text":"੧੦੭।","page":814,"lines":[{"gurmukhi":"ਤੇ ਕਹੇ ਸਰਬ ਨਰੇਸ। ਜੇ ਆ ਗਏ ਇਹ ਦੇਸਿ।","roman":"Te kahe sarab nares | je aa gae ih desi |","meaning_en":"All the kings who came to this land, those he told of:","page":814,"meaning_status":"draft"},{"gurmukhi":"ਕਰਿ ਅਸਟ ਦਸ੍ਯ ਪੁਰਾਨਿ। ਦਿਜ ਬਿਆਸ ਬੇਦ ਨਿਧਾਨ। ੧੦੭।","roman":"Kari asat dasy puraani | dij biaas bed nidhaan | 107 |","meaning_en":"the Brahmin Vyas, treasury of the Vedas, composed the eighteen Puranas,","page":814,"meaning_status":"draft"}]},{"type":"verse","number":[108],"number_text":"੧੦੮।","page":814,"lines":[{"gurmukhi":"ਕੀਨੇ ਅਠਾਰਹ ਪਰਬ। ਜਗ ਰੀਝੀਆ ਸੁਨਿ ਸਰਬ।","roman":"Keene athaarah parab | jag reejheeaa suni sarab |","meaning_en":"and made the eighteen Parvas; hearing it all, the world was delighted.","page":814,"meaning_status":"draft"},{"gurmukhi":"ਇਹ ਬਿਆਸ ਬ੍ਰਹਮ ਵਤਾਰ। ਭਏ ਪੰਚਮੋ ਮੁਖ ਚਾਰ। ੧੦੮।","roman":"Ih biaas braham vataar | bhae panchmo mukh chaar | 108 |","meaning_en":"This Vyas was the incarnation of Brahma; this was the fifth of the Four-faced one.","page":814,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਪੰਚਮੋਵਤਾਰ ਬ੍ਰਹਮਾ ਬਿਆਸ","roman":"Iti sree bachitr naatak granthe panchmovtaar brahmaa biaas","meaning_en":"Here ends, in the holy Bachittar Natak granth, (in the account of) the fifth incarnation of Brahma, Vyas,","page":814,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਰਾਜਾ ਅਜ ਕੋ ਰਾਜ ਸਮਾਪਤੰ। ੧੦। ੫।","roman":"Raajaa aj ko raaj samaaptan | 10 | 5 |","meaning_en":"the reign of King Aj. 10. 5.","page":814,"meaning_status":"draft"}],"page":814,"number":[10,5]}});
